/* NUR 525 Exam 3 — Vulnerable Populations, ATOD, Violence, School &
   Occupational Health, Faith Community Nursing, Bioterrorism & Disaster Management.
   Built from the uploaded Exam 3 material: the Exam 3 Study Guide (Weeks 7–10),
   the Week 7/8 and Week 10 objectives, the lecture decks, the Are You Ready
   worksheets and quiz, and the School Nursing case study.
   Each item states why the correct answer is right and why each other option is not. */
window.NUR525E3_DATA = {
  questions: [
    {"id": "n525e3q001", "exam": 1, "topic": "Health equity vs. equality", "type": "mcq", "bloom": "Application", "stem": "A city offers every resident the same free 30-day bus pass so they can reach the health center. Six months later the nurse finds that residents of one neighborhood still miss most appointments because no bus route runs within two miles of their homes. Which action best reflects health equity rather than equality?", "options": ["Add a shuttle that serves that neighborhood so its residents can also reach the health center", "Give every resident in the city a second free 30-day bus pass", "Extend the existing bus passes from 30 days to 90 days for everyone", "Remind the residents at each clinic visit that the bus pass is free of charge"], "correct": [0], "rationale": "Health equity means everyone has a fair and just opportunity to be healthier, which requires giving people what they need to reach the same outcome. Equality gives everyone the same thing. Because this neighborhood has no bus route, the identical pass does not produce identical access, so an equitable response supplies the different resource that closes the gap.", "whyNot": ["", "Repeating an identical benefit for everyone is equality; it does nothing about a neighborhood that has no route to ride.", "A longer pass is still a pass for a route that does not reach these residents, so the barrier is unchanged.", "Education does not create transportation that does not exist; the obstacle is structural, not a knowledge deficit."]},
    {"id": "n525e3q002", "exam": 1, "topic": "Defining vulnerability", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse is explaining to a group of nursing students what makes a population 'vulnerable' in community health nursing. Which statement by a student indicates correct understanding of the term?", "options": ["\"They are people who have already been diagnosed with at least one chronic disease.\"", "\"They have increased susceptibility to stressors that negatively affect their health outcomes.\"", "\"They are people who refuse to take responsibility for their own health behaviors.\"", "\"They are populations who live below the federal poverty guideline for their family size.\""], "correct": [1], "rationale": "A vulnerable population has increased susceptibility to current or potential stressors that negatively affect health outcomes. Members of these groups are more likely to develop problems when exposed to risk, have worse outcomes when they do, and experience health disparities.", "whyNot": ["Vulnerability describes heightened susceptibility to poor outcomes, not an existing diagnosis; many vulnerable people are not yet ill.", "", "This blames the individual and misstates the concept, which is about exposure to risk and limited resources rather than personal failing.", "Poverty is the leading cause of vulnerability but is not the definition; vulnerable groups also include refugees, older adults and abused persons."]},
    {"id": "n525e3q003", "exam": 1, "topic": "Health disparities", "type": "mcq", "bloom": "Analysis", "stem": "Reviewing county data, a nurse notes that infant mortality is more than twice as high in one census tract as in the county overall, and that the difference has persisted for a decade. Which conclusion is most accurate?", "options": ["This is expected statistical variation and needs no specific targeted response", "This indicates the residents are simply not using the prenatal services already offered", "This is a health disparity, a preventable difference in disease burden borne by a disadvantaged group", "This reflects underlying genetic differences between the populations being compared"], "correct": [2], "rationale": "A health disparity is a preventable difference in disease burden, injury, or opportunity for optimal health experienced by socially disadvantaged groups. The key words are preventable and patterned: a large, persistent, group-linked gap calls for targeted nursing intervention rather than acceptance.", "whyNot": ["A twofold difference sustained over ten years is a consistent pattern, not random variation, and the material defines such differences as preventable.", "This assumes a cause without data; access, quality, and social conditions must be assessed before blaming utilization.", "", "Attributing a social pattern to genetics ignores the social determinants the material identifies as the drivers of disparities."]},
    {"id": "n525e3q004", "exam": 1, "topic": "Population health", "type": "mcq", "bloom": "Application", "stem": "A nurse wants to practice from a population health perspective at a clinic that serves a large housing complex. Which activity best demonstrates that perspective?", "options": ["Teaching each child with asthma how to use a spacer correctly at every visit", "Refilling rescue inhalers promptly for the children already enrolled in the clinic", "Documenting each asthma exacerbation thoroughly in the individual health record", "Analyzing asthma visit rates across the complex to find which buildings are most affected"], "correct": [3], "rationale": "Population health concerns the health outcomes of a group and the distribution of those outcomes within the group. Nurses apply it by assessing aggregates rather than only individuals, which is what examining rates building by building accomplishes.", "whyNot": ["This is valuable individual care, but population health looks at outcomes and their distribution across an aggregate rather than one patient at a time.", "Serving enrolled individuals well does not describe or address the health of the whole group, including those not yet in care.", "Accurate charting supports individual care and may feed data upward, but by itself it is not an aggregate-level analysis.", ""]},
    {"id": "n525e3q005", "exam": 1, "topic": "Resilience and strengths", "type": "mcq", "bloom": "Application", "stem": "A nurse begins working with a neighborhood that has high poverty and a strong network of churches, a food cooperative, and an active tenants' association. Which approach best reflects the concept of resilience in vulnerable populations?", "options": ["Partner with the existing groups so the neighborhood's own strengths drive the health program", "Focus the assessment on cataloging the neighborhood's deficits and unmet needs", "Bring in an outside agency to run the program with its own staff and plan", "Delay any program until additional outside funding has been secured"], "correct": [0], "rationale": "The material stresses that vulnerable people can build resilience and achieve health equity with proper support and resources, and that nurses should leverage the population's strengths. Partnering with organizations the community already trusts does exactly that.", "whyNot": ["", "A deficit-only picture misses the assets the material says nurses should leverage and can reinforce a sense of helplessness.", "Importing a program without the community's involvement bypasses the strengths and relationships that sustain change after the nurse leaves.", "Waiting for money ignores resources already present and postpones work the existing organizations could begin now."]},
    {"id": "n525e3q006", "exam": 1, "topic": "Factors creating vulnerability", "type": "sata", "bloom": "Analysis", "stem": "A nurse is assessing why residents of a neighborhood experience poorer health than the surrounding city. Which findings are factors that create vulnerability? Select all that apply.", "options": ["Several overlapping chronic illnesses within the same households", "A single small corner store sells the only groceries within walking distance", "Industrial facilities located directly beside the residential blocks", "Most households have no vehicle and no public transit stop nearby", "The neighborhood has an active block association that meets monthly", "A majority of residents report attending a place of worship regularly"], "correct": [0, 1, 2, 3], "rationale": "Vulnerability is produced by social determinants of health and by overlapping, compounding risks: interconnected chronic illnesses, food insecurity and food deserts where small stores charge more than supermarkets, environmental hazards in the living environment, and the transportation barriers that follow from having no vehicle.", "whyNot": ["", "", "", "", "An organized association is a community strength that builds resilience, not a factor that creates vulnerability.", "Faith community participation is a source of support and a setting for health promotion rather than a risk factor."]},
    {"id": "n525e3q007", "exam": 1, "topic": "Food insecurity and food deserts", "type": "mcq", "bloom": "Analysis", "stem": "A client tells the nurse that the only store she can reach on foot is a small bodega where milk and produce cost nearly twice what the supermarket charges, and that she has no car to carry groceries home from the supermarket. How should the nurse interpret this finding?", "options": ["The client needs instruction on comparison shopping and budgeting", "The client lives in a food desert, which limits access to affordable, nutritious food", "The client is demonstrating a cultural preference for neighborhood stores", "The client should be referred for a complete nutritional assessment first"], "correct": [1], "rationale": "A food desert is an area with limited access to affordable, nutritious food. The material describes exactly this pattern: small bodegas charge more than large supermarkets, and without a vehicle a person cannot carry groceries home from the cheaper store. Community responses such as free community fridges address the access problem itself.", "whyNot": ["Teaching budgeting implies the problem is a skills deficit, but the client has already identified the price difference and cannot reach the cheaper store.", "", "Nothing suggests preference; she describes an absence of alternatives, which is a structural access problem.", "A nutrition assessment may follow, but it would not address the identified cause, which is access to affordable food."]},
    {"id": "n525e3q008", "exam": 1, "topic": "Poverty as the primary cause of vulnerability", "type": "mcq", "bloom": "Comprehension", "stem": "A nursing student asks which single factor is identified as the primary cause of vulnerability to health problems. Which response by the nurse is correct?", "options": ["Prejudice and discrimination experienced by minority groups", "Social isolation from family and community supports", "Poverty, described as the determinant of the determinants", "Breakdown of traditional family structures in the community"], "correct": [2], "rationale": "Poverty is the primary cause of vulnerability and is called the determinant of the determinants because it drives the other social determinants: unstable or marginal housing, physical, dental and mental health problems, food insecurity, and limited access to care.", "whyNot": ["Racism and prejudice contribute to vulnerability, but the material names poverty as the primary cause and the driver behind other determinants.", "Isolation worsens outcomes and appears among the risks, yet it is not identified as the primary cause.", "", "Changes in family structure are listed among factors increasing poverty rather than as the root cause of vulnerability itself."]},
    {"id": "n525e3q009", "exam": 1, "topic": "Public policy and health disparities", "type": "sata", "bloom": "Analysis", "stem": "A nurse is preparing testimony on how public policy affects vulnerable populations. Which policies would the nurse cite as examples that reduce health disparities? Select all that apply.", "options": ["Medicaid and the Children's Health Insurance Program", "SNAP, WIC, and school meal programs", "Housing First initiatives for people who are unhoused", "Funding for Federally Qualified and Migrant Health Centers", "Zoning that places polluting industry near low-income neighborhoods", "Eligibility rules that exclude recent immigrants from coverage"], "correct": [0, 1, 2, 3], "rationale": "Policies can either create inequity or reduce disparities. Those that reduce disparities expand coverage and material support: Medicaid and CHIP, nutrition programs such as SNAP, WIC and school meals, Housing First, minimum wage and paid leave, and funding for Federally Qualified and Migrant Health Centers. Redlining, exclusionary eligibility rules and polluting zoning are examples of policy creating inequity.", "whyNot": ["", "", "", "", "This concentrates environmental hazards where vulnerable people live and is an example of policy creating inequity.", "Excluding a group from benefits widens disparities rather than narrowing them."]},
    {"id": "n525e3q010", "exam": 1, "topic": "Wraparound services", "type": "mcq", "bloom": "Application", "stem": "A clinic serving a low-income population finds that most clients who are referred to the separate social services office across town never go. Which change best applies the principle of wraparound services?", "options": ["Mail each client a reminder letter about the social services appointment", "Ask clients to call the social services office before they leave the clinic", "Schedule the social services appointment for the same week as the clinic visit", "Place social service and benefits staff in the clinic so needs are met during one visit"], "correct": [3], "rationale": "Wraparound services, or a one-stop shop, provide multiple services during a single visit, combining health care with social and economic assistance. The material gives the reason directly: clients face transportation, time and cost barriers and may not return for a second appointment.", "whyNot": ["A reminder addresses forgetting, but the obstacle is the second trip itself, with its transportation, time and cost burdens.", "Making the call still leaves the client needing a separate visit on another day.", "Tightening the interval does not remove the need for a second trip, which is the barrier the material identifies.", ""]},
    {"id": "n525e3q011", "exam": 1, "topic": "Nursing strategies for health equity", "type": "sata", "bloom": "Application", "stem": "A nurse is beginning a new assignment with a vulnerable population. Which strategies should the nurse use to improve health equity? Select all that apply.", "options": ["Examine one's own attitudes, beliefs and biases about this group", "Show respect and compassion and follow through on what is promised", "Bring services to churches, schools, workplaces and mobile clinics", "Work to develop programs and policies that reduce environmental hazards", "Make reasonable assumptions about clients' needs to save assessment time", "Require clients to come to the main clinic so records stay in one place"], "correct": [0, 1, 2, 3], "rationale": "Nursing strategies to improve equity include building a trusting relationship through respect, compassion and reliability; analyzing one's own beliefs and biases, which the material emphasizes should be done always; providing comprehensive services where people already are; and reducing environmental hazards through program development, policy and advocacy.", "whyNot": ["", "", "", "", "The material directs nurses not to make assumptions; doing so risks misdirected care and damages the trust being built.", "Centralizing for the agency's convenience adds the access barriers that comprehensive community-based services are meant to remove."]},
    {"id": "n525e3q012", "exam": 1, "topic": "Nursing roles with vulnerable populations", "type": "mcq", "bloom": "Application", "stem": "A community health nurse identifies several residents with untreated hypertension during a neighborhood blood pressure event and connects each of them to a primary care provider. Which nursing role is the nurse demonstrating?", "options": ["Case finder", "Health program planner", "Monitor and evaluator of care", "Participant in health policy development"], "correct": [0], "rationale": "Case finding is the role of detecting people who have a health problem or are at risk but are not yet in care, and connecting them to services. Nurses with vulnerable populations also serve as health educator, counselor, direct care provider, community assessor, monitor and evaluator, case manager, advocate, program planner and policy participant.", "whyNot": ["", "Program planning designs and organizes services; this nurse is detecting individuals with an unrecognized condition and linking them to care.", "Monitoring and evaluation judge whether care already delivered is effective, which comes after people have been found and enrolled.", "Policy work addresses the rules and funding that shape services rather than identifying individual cases in the community."]},
    {"id": "n525e3q013", "exam": 1, "topic": "Complications of poverty", "type": "sata", "bloom": "Comprehension", "stem": "A nurse is teaching about the health consequences of living in poverty. Which complications should the nurse include? Select all that apply.", "options": ["Higher rates of chronic illness", "Increased infant morbidity and mortality", "Shorter life expectancy", "Hospitalization rates about three times higher than higher-income persons", "Fewer complications once a chronic disease is diagnosed", "Greater likelihood of completing recommended preventive screening"], "correct": [0, 1, 2, 3], "rationale": "The complications of poverty include increased chronic illness, increased infant morbidity and mortality, shorter life expectancy, more complex health problems and complications, and hospitalization rates three times higher than those of higher-income persons.", "whyNot": ["", "", "", "", "Poverty is associated with more complex health problems and more complications, not fewer.", "Limited access to care reduces preventive service use among people living in poverty."]},
    {"id": "n525e3q014", "exam": 1, "topic": "Factors increasing poverty", "type": "mcq", "bloom": "Analysis", "stem": "A nurse reviews economic changes in a community where a large plant has replaced many full-time positions with part-time shifts that carry no benefits. Which conclusion about poverty risk is best supported?", "options": ["Poverty risk is unchanged because residents remain employed", "Part-time work with little or no benefits is a recognized factor that increases poverty", "Poverty risk falls because more residents now hold some form of job", "Poverty risk depends only on whether residents finished high school"], "correct": [1], "rationale": "Factors that increase poverty include decreased earnings, increased unemployment, changes in the labor force, more female-headed households, inadequate education or job skills, more children born to single women, downsizing with competition for unskilled jobs, and part-time jobs with little or no benefits.", "whyNot": ["Employment alone does not prevent poverty; the material identifies reduced earnings and benefit-poor part-time jobs as factors that increase it.", "", "Spreading fewer hours across more workers lowers earnings per household and adds the risk of being uninsured.", "Inadequate education and job skills is one listed factor among several, not the only determinant."]},
    {"id": "n525e3q015", "exam": 1, "topic": "Assistance programs", "type": "mcq", "bloom": "Application", "stem": "A nurse is working with a pregnant client who has a 3-year-old child and reports running out of food before the end of each month. Which referral most directly provides supplemental foods along with nutrition education for this family?", "options": ["TANF", "CHIP", "WIC", "Head Start"], "correct": [2], "rationale": "WIC serves Women, Infants and Children, providing supplemental foods plus nutrition education for pregnant, postpartum and breastfeeding women and for infants and children under five who are at nutritional risk. This client is pregnant and has a child under five, so she fits the program's eligibility exactly.", "whyNot": ["Temporary Assistance for Needy Families provides time-limited cash assistance with work requirements, not supplemental foods and nutrition education.", "The Children's Health Insurance Program provides health coverage for children, which does not address the food shortage itself.", "", "Head Start provides early-childhood education along with health and nutrition services, but it is not the supplemental food program for a pregnant woman."]},
    {"id": "n525e3q016", "exam": 1, "topic": "Assistance programs", "type": "mcq", "bloom": "Comprehension", "stem": "A client asks the nurse which program would give her a monthly benefit she can use to buy groceries at the store. Which program should the nurse identify?", "options": ["Medicaid", "Head Start", "TANF", "SNAP"], "correct": [3], "rationale": "SNAP, the Supplemental Nutrition Assistance Program formerly known as food stamps, provides a monthly food-purchasing benefit that the client uses at the store.", "whyNot": ["Medicaid is federal-state health insurance for low-income people and pays for health care, not groceries.", "Head Start is an early-childhood education program that includes health and nutrition services for enrolled children.", "TANF provides time-limited cash assistance tied to work requirements rather than a dedicated food-purchasing benefit.", ""]},
    {"id": "n525e3q017", "exam": 1, "topic": "Respectful care in poverty", "type": "mcq", "bloom": "Application", "stem": "A client who lives in poverty comes to the clinic for a follow-up visit. Which nurse behavior best reflects what people living in poverty say they want from health care providers?", "options": ["Treat the client like everyone else and avoid making the client's poverty obvious", "Ask at the start of each visit whether the client intends to pay the bill", "Prescribe the most effective medication and address cost only if the client objects", "Explain the health risks of poverty so the client understands the urgency"], "correct": [0], "rationale": "People living in poverty ask to be treated like everyone else, without condescension and without having their poverty made obvious, and not to be prejudged. Providers should remember clients cannot always afford medicine and should suggest community programs such as food banks, churches, clothing centers and government aid.", "whyNot": ["", "The material specifically warns against prejudging in this way, which embarrasses the client and damages trust.", "Remembering that clients cannot always afford medicine is part of the expected approach, so cost should be considered proactively.", "Lecturing a client about their poverty is condescending and does not supply the resources the client needs."]},
    {"id": "n525e3q018", "exam": 1, "topic": "Homelessness: population trends", "type": "mcq", "bloom": "Analysis", "stem": "The shelter director tells the nurse she is surprised by how many children now stay at the shelter and asks whether this is unusual. Which response by the nurse is accurate?", "options": ["\"Most shelters see children only during the summer months.\"", "\"Families with children are the fastest-growing group among people who are unhoused.\"", "\"Children in shelters usually indicate the parents have refused available housing.\"", "\"The number of unhoused children is counted precisely each year, so trends are certain.\""], "correct": [1], "rationale": "Families with children are the fastest-growing homeless population. Poverty can lead to homelessness, and exact counts are difficult to obtain. In this shelter about half the residents are children, which fits the national trend.", "whyNot": ["Nothing in the material ties family homelessness to a season; family homelessness is a sustained, growing pattern.", "", "This blames the family and contradicts the described causes, which are rising housing costs, low wages and lost income.", "The material states that exact numbers of people who are unhoused are hard to count."], "caseId": "c1shelter", "caseTitle": "Case 1 - The Hope Street Family Shelter", "scenario": "The Hope Street Family Shelter houses 40 residents, about half of them children. A community health nurse holds a weekly clinic there. Among this week's residents are a mother and her two school-age children who lost their apartment six weeks ago after the mother's hours were cut, a 58-year-old man with untreated hypertension and chronic leg wounds who has been unhoused for three years, and a 24-year-old veteran with post-traumatic stress disorder who sleeps in the shelter only when the weather is cold. The shelter has one shared bathroom per floor, no refrigeration for residents' personal items, and a locked office where staff may store medications on request."},
    {"id": "n525e3q019", "exam": 1, "topic": "Health risks of homelessness", "type": "sata", "bloom": "Analysis", "stem": "The nurse plans assessments for the 58-year-old man who has been unhoused for three years. Which health problems associated with homelessness should the nurse specifically screen for? Select all that apply.", "options": ["Peripheral vascular disease and hypertension", "Infestations such as lice and scabies with impaired skin integrity", "Tuberculosis and respiratory infection", "Hypothermia or heat-related illness depending on the season", "Osteoporosis related to prolonged bed rest", "Hospital-acquired infection from frequent admissions"], "correct": [0, 1, 2, 3], "rationale": "Health effects of homelessness include hypothermia and heat illness, infestations and poor skin integrity, peripheral vascular disease and hypertension from being on the feet all day, diabetes and nutritional deficits, respiratory infection and COPD, tuberculosis, HIV and AIDS, trauma, mental illness and substance use.", "whyNot": ["", "", "", "", "People who are unhoused are typically on their feet all day rather than immobilized, so disuse-related bone loss is not a characteristic risk.", "The characteristic risks come from exposure, crowding and lack of hygiene access, not from repeated inpatient stays."], "caseId": "c1shelter", "caseTitle": "Case 1 - The Hope Street Family Shelter", "scenario": "The Hope Street Family Shelter houses 40 residents, about half of them children. A community health nurse holds a weekly clinic there. Among this week's residents are a mother and her two school-age children who lost their apartment six weeks ago after the mother's hours were cut, a 58-year-old man with untreated hypertension and chronic leg wounds who has been unhoused for three years, and a 24-year-old veteran with post-traumatic stress disorder who sleeps in the shelter only when the weather is cold. The shelter has one shared bathroom per floor, no refrigeration for residents' personal items, and a locked office where staff may store medications on request."},
    {"id": "n525e3q020", "exam": 1, "topic": "Chronic wound care in the unhoused", "type": "mcq", "bloom": "Application", "stem": "The nurse wants to improve healing of the chronic leg wounds seen in several shelter residents. Which action would best improve outcomes for this group?", "options": ["Provide antibiotics to all residents who have open wounds", "Hand out free boxes of bandages at the shelter entrance", "Offer daily access to a room with running water, soap and dressing supplies", "Schedule residents to return frequently so the nurse can monitor the wounds"], "correct": [2], "rationale": "The root cause of poor wound healing in this population is the absence of a place to clean and care for wounds. Providing daily access to running water, soap and dressings addresses that cause directly. Antibiotics for everyone is inappropriate and bandages alone do not solve the hygiene problem.", "whyNot": ["Treating everyone with antibiotics is inappropriate, promotes resistance, and does not address why the wounds are not healing.", "Supplies alone do not help if residents have nowhere clean to wash the wound and change the dressing.", "", "Monitoring documents deterioration without changing the hygiene conditions that are preventing healing."], "caseId": "c1shelter", "caseTitle": "Case 1 - The Hope Street Family Shelter", "scenario": "The Hope Street Family Shelter houses 40 residents, about half of them children. A community health nurse holds a weekly clinic there. Among this week's residents are a mother and her two school-age children who lost their apartment six weeks ago after the mother's hours were cut, a 58-year-old man with untreated hypertension and chronic leg wounds who has been unhoused for three years, and a 24-year-old veteran with post-traumatic stress disorder who sleeps in the shelter only when the weather is cold. The shelter has one shared bathroom per floor, no refrigeration for residents' personal items, and a locked office where staff may store medications on request."},
    {"id": "n525e3q021", "exam": 1, "topic": "Barriers to care for the unhoused", "type": "sata", "bloom": "Analysis", "stem": "A resident is prescribed a daily antihypertensive and a refrigerated medication. Which barriers in this shelter should the nurse anticipate will affect the resident's ability to take them? Select all that apply.", "options": ["No refrigeration is available for residents' personal items", "The resident may have no address or phone for pharmacy contact", "Keeping medications safe from theft or loss is difficult in shared space", "Transportation to the pharmacy may not be available", "The shelter has a locked office where staff can store medications", "The resident has been told the name and purpose of each medication"], "correct": [0, 1, 2, 3], "rationale": "Barriers to care for people who are unhoused include lack of identification, address, phone, transportation and storage for medications, and the material notes specifically that keeping medications safe is hard. The locked office is an asset the nurse can use, not a barrier.", "whyNot": ["", "", "", "", "This is a resource that helps solve the storage and safety problem rather than a barrier to overcome.", "Having been taught about the medication supports adherence; the obstacles here are practical and structural."], "caseId": "c1shelter", "caseTitle": "Case 1 - The Hope Street Family Shelter", "scenario": "The Hope Street Family Shelter houses 40 residents, about half of them children. A community health nurse holds a weekly clinic there. Among this week's residents are a mother and her two school-age children who lost their apartment six weeks ago after the mother's hours were cut, a 58-year-old man with untreated hypertension and chronic leg wounds who has been unhoused for three years, and a 24-year-old veteran with post-traumatic stress disorder who sleeps in the shelter only when the weather is cold. The shelter has one shared bathroom per floor, no refrigeration for residents' personal items, and a locked office where staff may store medications on request."},
    {"id": "n525e3q022", "exam": 1, "topic": "Homelessness and mental illness", "type": "mcq", "bloom": "Comprehension", "stem": "A staff member asks the nurse how common severe mental illness is among people who are unhoused. Which statement by the nurse is accurate?", "options": ["Nearly all people who are unhoused have a severe mental illness", "Severe mental illness is rare among people who are unhoused", "Severe mental illness occurs at the same rate as in the general population", "About one in five people who are unhoused have a severe mental illness"], "correct": [3], "rationale": "One in five people who are unhoused have a severe mental illness. Knowing the proportion helps the nurse plan screening and referral without stereotyping every resident.", "whyNot": ["Overstating the proportion stereotypes the population and ignores the economic causes of homelessness.", "This understates a substantial and well-documented proportion and could lead the nurse to miss needed screening.", "The rate among people who are unhoused is considerably higher than in the general population.", ""], "caseId": "c1shelter", "caseTitle": "Case 1 - The Hope Street Family Shelter", "scenario": "The Hope Street Family Shelter houses 40 residents, about half of them children. A community health nurse holds a weekly clinic there. Among this week's residents are a mother and her two school-age children who lost their apartment six weeks ago after the mother's hours were cut, a 58-year-old man with untreated hypertension and chronic leg wounds who has been unhoused for three years, and a 24-year-old veteran with post-traumatic stress disorder who sleeps in the shelter only when the weather is cold. The shelter has one shared bathroom per floor, no refrigeration for residents' personal items, and a locked office where staff may store medications on request."},
    {"id": "n525e3q023", "exam": 1, "topic": "Nursing role with the unhoused", "type": "mcq", "bloom": "Application", "stem": "The nurse is preparing to begin working with the shelter residents for the first time. According to the sequence described for nursing care of people who are unhoused, which action should come first?", "options": ["Assess the nurse's own biases about people who are unhoused", "Determine which community services already exist for this population", "Complete a physical assessment on each resident in the shelter", "Advocate with the city council for additional shelter funding"], "correct": [0], "rationale": "The described nursing role proceeds in order: assess your own bias, then provide care and gain trust, then assess needs, then ensure services exist and connect people to them, then advocate. Examining personal bias first prevents assumptions from distorting every step that follows.", "whyNot": ["", "Confirming that services exist comes later in the sequence, after trust has been established and needs assessed.", "Needs assessment follows the establishment of trust, and residents are unlikely to engage with a nurse they do not trust.", "Advocacy is part of the role but is the final step rather than the starting point for a nurse new to this population."], "caseId": "c1shelter", "caseTitle": "Case 1 - The Hope Street Family Shelter", "scenario": "The Hope Street Family Shelter houses 40 residents, about half of them children. A community health nurse holds a weekly clinic there. Among this week's residents are a mother and her two school-age children who lost their apartment six weeks ago after the mother's hours were cut, a 58-year-old man with untreated hypertension and chronic leg wounds who has been unhoused for three years, and a 24-year-old veteran with post-traumatic stress disorder who sleeps in the shelter only when the weather is cold. The shelter has one shared bathroom per floor, no refrigeration for residents' personal items, and a locked office where staff may store medications on request."},
    {"id": "n525e3q024", "exam": 1, "topic": "Veterans as a vulnerable subgroup", "type": "mcq", "bloom": "Application", "stem": "The nurse learns that the 24-year-old veteran with post-traumatic stress disorder is not connected to any services. Which nursing action is most appropriate?", "options": ["Advise him to come to the shelter every night regardless of the weather", "Refer him to veteran-specific community programs such as a local veterans' organization", "Explain that post-traumatic stress disorder must resolve before housing can be addressed", "Document that he declines services since he uses the shelter only in cold weather"], "correct": [1], "rationale": "Veterans are identified as a key subgroup among people who are unhoused, with dedicated community resources such as Operation Stand Down and Veterans Inc. in Worcester. Connecting the client to services that exist for his population fits the nursing role of ensuring services exist and linking people to them.", "whyNot": ["Directing his choices without addressing his needs does not connect him to care and may end the relationship.", "", "Housing and mental health needs are addressed together; making housing conditional on recovery creates another barrier.", "Intermittent shelter use is not a refusal of services, and documenting it as such forecloses outreach."], "caseId": "c1shelter", "caseTitle": "Case 1 - The Hope Street Family Shelter", "scenario": "The Hope Street Family Shelter houses 40 residents, about half of them children. A community health nurse holds a weekly clinic there. Among this week's residents are a mother and her two school-age children who lost their apartment six weeks ago after the mother's hours were cut, a 58-year-old man with untreated hypertension and chronic leg wounds who has been unhoused for three years, and a 24-year-old veteran with post-traumatic stress disorder who sleeps in the shelter only when the weather is cold. The shelter has one shared bathroom per floor, no refrigeration for residents' personal items, and a locked office where staff may store medications on request."},
    {"id": "n525e3q025", "exam": 1, "topic": "Levels of prevention", "type": "mcq", "bloom": "Analysis", "stem": "A nurse plans three activities for a vulnerable community: a nutrition class at the community center, blood pressure screening at a church, and a support group for residents already diagnosed with diabetes. How should the nurse classify these three activities in order?", "options": ["Secondary, primary, tertiary", "Primary, tertiary, secondary", "Primary, secondary, tertiary", "Tertiary, secondary, primary"], "correct": [2], "rationale": "Primary prevention stops the problem before it occurs through education, immunization, policy and advocacy. Secondary prevention is early detection and prompt treatment, signaled by words such as screen, assess and test. Tertiary prevention limits disability and prevents recurrence or complications of an existing problem, including rehabilitation, support groups and chronic disease management.", "whyNot": ["A nutrition class prevents the problem before it occurs and is primary; screening detects disease early and is secondary, so the first two are reversed here.", "Blood pressure screening is early detection, which is secondary, while a support group for people already diagnosed is tertiary.", "", "This reverses the sequence entirely; health education to prevent a problem is primary, not tertiary."]},
    {"id": "n525e3q026", "exam": 2, "topic": "Teen pregnancy risk", "type": "mcq", "bloom": "Application", "stem": "A 16-year-old client is seen in the first trimester of her first pregnancy. She has no chronic illness, her vital signs are normal, and her physical examination is unremarkable. How should the nurse classify this pregnancy?", "options": ["Low risk, because she has no chronic illness and normal findings today", "Risk cannot be determined until the second trimester screening is complete", "Low risk, because she presented during the first trimester", "High risk, because all teen pregnancies are considered high risk"], "correct": [3], "rationale": "All teen pregnancies are high risk. Teens face low birth weight and preterm delivery, poor nutrition, inadequate weight gain, more violence during pregnancy than adults, and the stresses of infant care, so the pregnancy is managed as high risk even when the initial assessment is normal.", "whyNot": ["A normal initial examination does not remove the risk; the material states that all teen pregnancies are high risk regardless of current findings.", "Deferring the designation delays the intensified monitoring and support that a teen pregnancy warrants from the start.", "Early presentation is favorable and is exactly what nurses want, but it does not change the high-risk classification.", ""]},
    {"id": "n525e3q027", "exam": 2, "topic": "Teen pregnancy priority", "type": "mcq", "bloom": "Application", "stem": "A nurse is planning education and support for a pregnant 16-year-old in her first trimester. Which consideration should the nurse prioritize?", "options": ["Encouraging early initiation of prenatal care", "Advising the teenager to continue strenuous physical activities", "Recommending a high-calorie diet to support rapid fetal growth", "Emphasizing the importance of planning for additional pregnancies"], "correct": [0], "rationale": "Early initiation of prenatal care is the most essential consideration because all teen pregnancies are high risk for low birth weight, preterm delivery, poor nutrition and violence. Many teens delay care, so securing and maintaining early engagement addresses the risk that drives the poorest outcomes.", "whyNot": ["", "This is not an appropriate recommendation in pregnancy and does not address the risks that make teen pregnancy high risk.", "Nutrition matters, but pushing calories alone is not the priority and ignores the quality of the diet and the teen's own growth needs.", "Planning future pregnancies is not the priority during a current high-risk pregnancy that needs immediate prenatal engagement."]},
    {"id": "n525e3q028", "exam": 2, "topic": "Delayed prenatal care in teens", "type": "sata", "bloom": "Analysis", "stem": "A nurse is designing outreach to reduce delayed prenatal care among pregnant adolescents. Which reasons for the delay should the outreach address? Select all that apply.", "options": ["Denial, or hoping the pregnancy will just go away", "Fear of telling parents or a partner", "Worry that the visit will not be kept confidential", "Not recognizing the signs of pregnancy", "Not knowing what resources, insurance or transportation are available", "Confidence that prenatal care is unnecessary for a healthy teenager"], "correct": [0, 1, 2, 3, 4], "rationale": "Pregnant teens delay care because of denial or hoping the problem will go away, fear of telling parents or a partner, confidentiality worries, not recognizing the signs of pregnancy, and lack of knowledge about resources, insurance or transportation. Outreach that names and addresses these specific barriers reaches teens earlier.", "whyNot": ["", "", "", "", "", "The listed reasons involve fear, denial and lack of knowledge rather than a reasoned judgment that care is unneeded."]},
    {"id": "n525e3q029", "exam": 2, "topic": "Long-term outcomes for teen mothers", "type": "mcq", "bloom": "Analysis", "stem": "A nurse wants to improve long-term health outcomes for pregnant teens living in poverty and for their children. Which action would most likely accomplish this?", "options": ["Offer courses on infant care and parenting skills", "Develop programs that allow teen mothers to complete their education", "Monitor the pregnant teens closely to detect early problems in pregnancy", "Teach the teens about the body changes they will experience in pregnancy"], "correct": [1], "rationale": "Completing education breaks the poverty cycle: lack of education leads to low earnings, which puts the family at risk for disparities, while education builds lasting resilience. The other options address short-term needs within this pregnancy rather than long-term outcomes for the mother and child.", "whyNot": ["Parenting classes meet an immediate need but do not change the family's long-term economic trajectory.", "", "Close monitoring improves the outcome of this pregnancy; it is short-term and does not alter the conditions that sustain poverty.", "Education about physiologic changes supports the current pregnancy but has no effect on long-term outcomes."]},
    {"id": "n525e3q030", "exam": 2, "topic": "Mature minor doctrine", "type": "mcq", "bloom": "Comprehension", "stem": "A 16-year-old asks whether she can consent to a non-emergency clinic visit without a parent present. Which principle should guide the nurse's response?", "options": ["Minors may never consent to their own care until they reach age 18", "Minors may consent to any care at all once they are able to describe the treatment", "The mature minor doctrine may allow her to make non-emergent medical decisions, depending on state law", "Consent requirements for minors are set by federal law and are the same nationwide"], "correct": [2], "rationale": "The mature minor doctrine allows under-aged adolescents to make non-emergent medical decisions, and nurses must know their own state's laws because the rules vary. Related protected information such as sexually transmitted infection treatment, pregnancy and birth control is kept separate from records parents may view.", "whyNot": ["This ignores the mature minor doctrine and would wrongly turn away adolescents who are legally able to consent.", "The doctrine applies to non-emergent decisions and is bounded by state law rather than by the minor's explanation.", "", "These laws vary by state, which is why the nurse must know the law where care is given."]},
    {"id": "n525e3q031", "exam": 2, "topic": "Teen pregnancy: violence and nutrition", "type": "sata", "bloom": "Analysis", "stem": "A nurse is assessing a pregnant 15-year-old. Which areas of concern specific to adolescent pregnancy should the nurse assess? Select all that apply.", "options": ["Exposure to violence, since teens experience more violence in pregnancy than adults do", "Adequacy of weight gain, since a younger teen may need to gain more than an older mother", "Nutritional intake and risk of low birth weight or preterm delivery", "Readiness for the reality of around-the-clock infant care", "Need for a labor induction at 37 weeks because of her age", "Whether she has already chosen a pediatric subspecialist for the infant"], "correct": [0, 1, 2, 3], "rationale": "Areas of concern in teen pregnancy include violence, with teens experiencing more violence during pregnancy than adults and sometimes protecting partners out of fear or helplessness; late initiation of prenatal care; low birth weight and preterm delivery; poor nutrition; weight gain, because younger teens may need to gain more than mothers aged 17 and older to achieve the same birth weight since they are still growing; and infant care, where stress should be monitored because it can lead to neglect or abuse.", "whyNot": ["", "", "", "", "Age alone is not an indication for induction, and nothing in the material directs early delivery for adolescents.", "This is not an identified area of concern for adolescent pregnancy and does not address her risks."]},
    {"id": "n525e3q032", "exam": 2, "topic": "Supporting the pregnant teen", "type": "mcq", "bloom": "Application", "stem": "A 17-year-old who is pregnant tells the nurse she is worried she will have to give up her education and career goals. Which response by the nurse is most appropriate?", "options": ["\"It is essential to prioritize your education and career over parenting responsibilities.\"", "\"Consider placing your baby for adoption so you can focus on school and a career.\"", "\"You should delay school and career plans until your child is older.\"", "\"Let's look at resources and supports that can help you balance parenting and your education.\""], "correct": [3], "rationale": "Keeping teen mothers in school is a central intervention because education builds lasting resilience and breaks the poverty cycle. Exploring resources and supports with the client addresses her stated concern without making the decision for her, and allows referral to support groups, WIC, Head Start and Medicaid.", "whyNot": ["Telling the client how to rank her roles dismisses her concern and substitutes the nurse's values for hers.", "Directing a major, personal decision she did not raise is coercive and not what she asked about.", "This forecloses the education that most improves long-term outcomes for the mother and child.", ""]},
    {"id": "n525e3q033", "exam": 2, "topic": "Mental illness in the community", "type": "mcq", "bloom": "Application", "stem": "A community health nurse is planning services for people with mental illness in a low-income neighborhood. Which approach best fits the nursing role described for this population?", "options": ["Build trust, assess needs, connect people to services and advocate for the resources they lack", "Focus services on those who have already been hospitalized for a psychiatric condition", "Require clients to achieve stable housing before mental health services begin", "Refer all clients to inpatient psychiatric care as the first step in the plan"], "correct": [0], "rationale": "People with mental illness are a vulnerable population, and one in five people who are unhoused have a severe mental illness. The nursing role follows the same sequence used with other vulnerable groups: examine bias, gain trust, assess needs, ensure services exist and connect people to them, and advocate.", "whyNot": ["", "Limiting outreach to people with prior admissions misses those at risk and those never connected to care.", "Making services conditional adds a barrier for a population whose housing instability is often tied to the illness itself.", "Inpatient care is not the entry point for community-based services and is not indicated for most people in this group."]},
    {"id": "n525e3q034", "exam": 2, "topic": "Rural health status", "type": "sata", "bloom": "Comprehension", "stem": "A nurse is describing the health status of rural populations compared with urban populations. Which characteristics are accurate? Select all that apply.", "options": ["Poorer self-perceived health", "Higher rates of smoking, alcohol use and obesity", "More chronic disease such as heart disease, COPD, hypertension and diabetes", "Less engagement in preventive health behavior", "Higher rates of health insurance coverage than urban residents", "Greater likelihood of seeking care early in an illness"], "correct": [0, 1, 2, 3], "rationale": "Rural populations report poorer self-perceived health, engage in less preventive behavior, have more smoking, alcohol use and obesity, carry more chronic disease, and are less likely to seek care. They are also poorer on average and at higher risk of being under- or uninsured.", "whyNot": ["", "", "", "", "Rural residents are at higher risk of being under-insured or uninsured, not better covered.", "Rural residents are less likely to seek care, and travel time and distance further limit access."]},
    {"id": "n525e3q035", "exam": 2, "topic": "Rural barriers to care", "type": "mcq", "bloom": "Analysis", "stem": "A rural clinic finds that many residents miss appointments. The county has no public transportation, most residents work unpredictable hours, and the nearest specialist is 70 miles away. Which nursing conclusion is best supported?", "options": ["Residents are demonstrating a cultural preference for avoiding medical care", "Structural barriers including distance, transportation and work hours are limiting access", "Residents lack adequate health literacy about the importance of follow-up", "The clinic should discharge residents who repeatedly miss scheduled appointments"], "correct": [1], "rationale": "Rural barriers include higher poverty, cultural norms, low health literacy, language and education gaps, limited or absent public transportation, unpredictable work hours, low population density with no economy of scale, limited resources and personnel, and little access to healthy food and physical activity. The findings here name the structural ones directly.", "whyNot": ["Cultural norms are one listed barrier, but the specific findings here describe concrete structural obstacles that must be addressed first.", "", "Low health literacy appears among rural barriers, yet nothing in these findings points to it as the cause of the missed visits.", "Discharging clients punishes them for barriers outside their control and worsens access for a population already underserved."]},
    {"id": "n525e3q036", "exam": 2, "topic": "Rural provider shortage", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse reviews a federal designation that identifies areas with too few primary care providers and unlocks funding and loan repayment to attract clinicians. Which designation is the nurse reviewing?", "options": ["Federally Qualified Health Center", "Community Emergency Response Team", "Health Professional Shortage Area", "Medical Reserve Corps unit"], "correct": [2], "rationale": "A Health Professional Shortage Area is a federal designation for areas with too few providers; it unlocks funding and loan repayment to attract clinicians. Rural provider shortages are characterized by clinicians practicing for decades in one community, covering several counties with a small staff for a large area.", "whyNot": ["This designation identifies a type of clinic that receives federal support to serve underserved populations, not a geographic shortage designation.", "This is a program of trained disaster volunteers and has nothing to do with provider supply.", "", "The Medical Reserve Corps organizes medical volunteers for emergencies rather than designating shortage areas."]},
    {"id": "n525e3q037", "exam": 2, "topic": "Rural nursing practice", "type": "mcq", "bloom": "Application", "stem": "A nurse is considering a position as the only nurse serving several small rural communities. Which professional challenge specific to rural practice should the nurse anticipate?", "options": ["Narrow clinical scope limited to a single patient population", "Limited autonomy because of close supervision by specialists", "Difficulty forming relationships with clients over time", "Professional isolation from other nurses and health professionals"], "correct": [3], "rationale": "The professional challenge named for rural nursing is lack of resources and of other professionals to interact with, that is, professional isolation. Rural practice also brings wide clinical variety, close client relationships and greater autonomy, spanning school nursing, family planning, prenatal care, HIV care, emergency services, children with special needs, mental health and older-adult services.", "whyNot": ["Rural practice involves wide clinical variety rather than a narrow scope, spanning school nursing, prenatal care, emergency services and mental health.", "Rural nurses typically have greater autonomy, not less, because specialists and supervisors are scarce.", "Rural practice is characterized by close relationships with clients, which is one of its distinguishing features.", ""]},
    {"id": "n525e3q038", "exam": 2, "topic": "Rural maternal and child health", "type": "mcq", "bloom": "Analysis", "stem": "A nurse is identifying women at highest risk for poor pregnancy outcomes in a rural region. Which groups should the nurse target for intensified outreach?", "options": ["Women on or near Native American reservations, migrant workers, Black women, and survivors of sexual assault", "Women who have had more than two previous uncomplicated pregnancies and live near a hospital", "Women who have relocated into the rural region at some point within the past five years", "Women who are older than 35 years of age and live within 10 miles of a regional hospital"], "correct": [0], "rationale": "Rural women and children have higher infant and maternal morbidity, fewer available specialists, and extreme variation in pregnancy outcomes. The highest-risk groups named are women on or near Native American reservations, migrant workers, Black women and victims of sexual assault.", "whyNot": ["", "Prior uncomplicated pregnancies are not identified as a high-risk marker in the rural material.", "Recent relocation is not among the identified highest-risk groups, although mobility is a barrier for migrant families.", "Proximity to a hospital reduces access barriers, and this combination is not among the named highest-risk groups."]},
    {"id": "n525e3q039", "exam": 2, "topic": "Migrant health: access barriers", "type": "mcq", "bloom": "Analysis", "stem": "The nurse is identifying what most limits Maria's access to health care. Which assessment finding represents her greatest barrier?", "options": ["Her preference for Spanish, which indicates low health literacy", "Transportation, inflexible work hours and financial insecurity from lost wages", "Her lack of interest in preventive health services", "Her unfamiliarity with the symptoms that require medical attention"], "correct": [1], "rationale": "The barriers to care for migrant farmworkers include not knowing about services, inability to afford care, the availability and hours of service, transportation, mobility and tracking as families move, language, discrimination, fears about documentation status, and lost wages from missing work. Maria has no car, works 10 to 12 hour days and would lose pay to attend an appointment.", "whyNot": ["Speaking Spanish is a language difference requiring interpretation; it is not the same as low health literacy and should not be treated as one.", "", "Nothing suggests disinterest; she presented at the first accessible clinic, which indicates she will use care she can reach.", "She recognized both her back pain and feeling unwell after spraying, so symptom recognition is not her limiting problem."], "caseId": "c2maria", "caseTitle": "Case 2 - Maria, a seasonal farmworker", "scenario": "Maria is 34 years old and works as a seasonal farmworker, moving with her husband and three children among farms in three states as the harvests change. She speaks Spanish and limited English. She works 10 to 12 hours a day picking and packing produce, and the family lives in grower-provided housing several miles from the nearest town. She has no car and relies on a crew leader for rides. Her last clinic visit was in another state 14 months ago. She comes to a mobile clinic today because of persistent low back pain, and mentions that she sometimes feels unwell after the fields are sprayed."},
    {"id": "n525e3q040", "exam": 2, "topic": "Migrant health: access intervention", "type": "mcq", "bloom": "Application", "stem": "The health department asks the nurse to recommend one intervention that would most improve access to care for Maria and other farmworkers in the county. Which recommendation is best?", "options": ["Extended evening hours at the existing clinic in town", "Printed Spanish-language brochures distributed at the grower's housing", "Mobile clinics staffed with qualified Spanish interpretation", "A telephone line where farmworkers can request an appointment"], "correct": [2], "rationale": "Mobile clinics with qualified interpretation bring care to where migrant workers already are, which removes the transportation barrier, and supplies professional interpretation rather than relying on family members. Culturally competent care for this population requires qualified interpreters, not family, and follow-up planning that works with the family's mobility.", "whyNot": ["Later hours help with work schedules but still require transportation to town, which these families do not have.", "Written material alone does not deliver care and assumes a level of reading the material does not establish.", "", "A phone line still ends in a trip the family cannot make, and does not address language during the visit itself."], "caseId": "c2maria", "caseTitle": "Case 2 - Maria, a seasonal farmworker", "scenario": "Maria is 34 years old and works as a seasonal farmworker, moving with her husband and three children among farms in three states as the harvests change. She speaks Spanish and limited English. She works 10 to 12 hours a day picking and packing produce, and the family lives in grower-provided housing several miles from the nearest town. She has no car and relies on a crew leader for rides. Her last clinic visit was in another state 14 months ago. She comes to a mobile clinic today because of persistent low back pain, and mentions that she sometimes feels unwell after the fields are sprayed."},
    {"id": "n525e3q041", "exam": 2, "topic": "Migrant occupational health problems", "type": "sata", "bloom": "Analysis", "stem": "Considering the work Maria performs, which occupational health problems should the nurse assess for? Select all that apply.", "options": ["Chronic neck and back pain from prolonged standing, bending and over-exertion", "Heat-related illness and dehydration", "Eye problems from dust and chemicals", "Skin cancer from prolonged sun exposure", "Green tobacco sickness from nicotine absorbed through the skin", "Decompression illness from working at altitude"], "correct": [0, 1, 2, 3], "rationale": "Occupational health problems for migrant farmworkers include prolonged standing, bending and over-exertion causing chronic neck and back pain; heat and dehydration; pesticide exposure, often without being informed of the risk; eye problems from dust and chemicals; skin cancer from the sun; tractor and equipment injuries; green tobacco sickness in tobacco workers; and poor housing and nutrition.", "whyNot": ["", "", "", "", "Green tobacco sickness occurs in workers handling wet tobacco leaves; Maria picks and packs produce.", "This is not an agricultural hazard and does not relate to any of the work described."], "caseId": "c2maria", "caseTitle": "Case 2 - Maria, a seasonal farmworker", "scenario": "Maria is 34 years old and works as a seasonal farmworker, moving with her husband and three children among farms in three states as the harvests change. She speaks Spanish and limited English. She works 10 to 12 hours a day picking and packing produce, and the family lives in grower-provided housing several miles from the nearest town. She has no car and relies on a crew leader for rides. Her last clinic visit was in another state 14 months ago. She comes to a mobile clinic today because of persistent low back pain, and mentions that she sometimes feels unwell after the fields are sprayed."},
    {"id": "n525e3q042", "exam": 2, "topic": "Acute pesticide toxicity", "type": "mcq", "bloom": "Analysis", "stem": "Later that week Maria returns after entering a field that was treated that morning. She reports nausea, dizziness, sweating and abdominal cramps, and her heart rate is 56 beats per minute. Which action should the nurse take?", "options": ["Give oral fluids and have her rest in the shade for an hour", "Schedule her for a follow-up visit at the mobile clinic next week", "Document the symptoms and advise her to avoid the field for 24 hours", "Arrange urgent medical evaluation and begin decontamination"], "correct": [3], "rationale": "Nausea, dizziness, sweating, cramps and a heart rate of 56 after entering a treated field fit acute organophosphate pesticide poisoning, which produces cholinergic excess: sweating, salivation, tearing, nausea, vomiting and diarrhea, abdominal cramps, bradycardia, pinpoint pupils, bronchorrhea and muscle twitching, progressing to respiratory failure. Priority actions are removing contaminated clothing, washing skin with soap and water, airway support and urgent medical care.", "whyNot": ["Treating this as heat illness delays recognition of a toxic exposure that can progress to respiratory failure.", "A week's delay is unsafe for an acute exposure with cholinergic signs that may worsen over hours.", "Avoiding re-exposure is necessary but insufficient; she already has symptoms requiring evaluation and decontamination now.", ""], "caseId": "c2maria", "caseTitle": "Case 2 - Maria, a seasonal farmworker", "scenario": "Maria is 34 years old and works as a seasonal farmworker, moving with her husband and three children among farms in three states as the harvests change. She speaks Spanish and limited English. She works 10 to 12 hours a day picking and packing produce, and the family lives in grower-provided housing several miles from the nearest town. She has no car and relies on a crew leader for rides. Her last clinic visit was in another state 14 months ago. She comes to a mobile clinic today because of persistent low back pain, and mentions that she sometimes feels unwell after the fields are sprayed."},
    {"id": "n525e3q043", "exam": 2, "topic": "Pesticide exposure: primary prevention", "type": "mcq", "bloom": "Application", "stem": "The nurse plans primary prevention for pesticide exposure among the farmworkers in this county. Which intervention belongs at this level of prevention?", "options": ["Task-appropriate personal protective equipment and pesticide-safety training", "Screening symptomatic workers for signs of pesticide exposure", "Coordinating rehabilitation after a worker is diagnosed with poisoning", "Treating a worker who has been diagnosed with acute toxicity"], "correct": [0], "rationale": "Primary prevention stops the problem before it occurs. For pesticide exposure that means task-appropriate protective equipment, pesticide-safety training, engineering controls, safe re-entry intervals and advocacy for the Worker Protection Standard. Screening exposed or symptomatic workers is secondary, and treatment, follow-up and rehabilitation after a diagnosis are tertiary.", "whyNot": ["", "Screening to detect a problem early is secondary prevention.", "Rehabilitation and follow-up for an existing diagnosis is tertiary prevention.", "Treating a diagnosed condition is tertiary prevention in this framework."], "caseId": "c2maria", "caseTitle": "Case 2 - Maria, a seasonal farmworker", "scenario": "Maria is 34 years old and works as a seasonal farmworker, moving with her husband and three children among farms in three states as the harvests change. She speaks Spanish and limited English. She works 10 to 12 hours a day picking and packing produce, and the family lives in grower-provided housing several miles from the nearest town. She has no car and relies on a crew leader for rides. Her last clinic visit was in another state 14 months ago. She comes to a mobile clinic today because of persistent low back pain, and mentions that she sometimes feels unwell after the fields are sprayed."},
    {"id": "n525e3q044", "exam": 2, "topic": "Pesticide exposure: tertiary prevention", "type": "mcq", "bloom": "Application", "stem": "Maria is diagnosed with pesticide poisoning and completes treatment. Which nursing action represents tertiary prevention for her?", "options": ["Teach the crew the early warning signs of pesticide toxicity", "Coordinate follow-up and rehabilitation and prevent re-exposure", "Provide the crew with protective equipment before the next spraying", "Screen the other workers on Maria's crew for symptoms of exposure"], "correct": [1], "rationale": "Tertiary prevention limits disability and prevents recurrence or complications of an existing problem. For a worker already diagnosed with pesticide poisoning this means treatment follow-up, rehabilitation, preventing re-exposure, and advocacy for wages and worker protections.", "whyNot": ["Teaching workers to recognize early signs supports early detection, which is secondary prevention.", "", "Supplying protective equipment before exposure occurs is primary prevention.", "Screening the exposed crew to find problems early is secondary prevention."], "caseId": "c2maria", "caseTitle": "Case 2 - Maria, a seasonal farmworker", "scenario": "Maria is 34 years old and works as a seasonal farmworker, moving with her husband and three children among farms in three states as the harvests change. She speaks Spanish and limited English. She works 10 to 12 hours a day picking and packing produce, and the family lives in grower-provided housing several miles from the nearest town. She has no car and relies on a crew leader for rides. Her last clinic visit was in another state 14 months ago. She comes to a mobile clinic today because of persistent low back pain, and mentions that she sometimes feels unwell after the fields are sprayed."},
    {"id": "n525e3q045", "exam": 2, "topic": "Culturally competent care and teach-back", "type": "mcq", "bloom": "Application", "stem": "Through an interpreter the nurse teaches Maria how to take a new medication. Maria nods and says yes throughout the explanation. Which action should the nurse take next?", "options": ["Document that the teaching was understood because she agreed", "Give her a written Spanish handout and end the teaching session", "Ask Maria to explain in her own words how she will take the medication", "Repeat the same explanation a second time to reinforce it"], "correct": [2], "rationale": "The material notes specifically that Mexican-immigrant clients may nod as if they understand when they do not, and directs the nurse to use teach-back. Asking the client to explain the plan in her own words verifies understanding and identifies exactly what to re-teach.", "whyNot": ["Nodding and agreeing may be courtesy rather than comprehension, so agreement alone does not verify understanding.", "A handout supplements teaching but does not confirm that she understood, and assumes a reading level not established.", "", "Repeating identical wording does not reveal what she misunderstood, and does not check comprehension."], "caseId": "c2maria", "caseTitle": "Case 2 - Maria, a seasonal farmworker", "scenario": "Maria is 34 years old and works as a seasonal farmworker, moving with her husband and three children among farms in three states as the harvests change. She speaks Spanish and limited English. She works 10 to 12 hours a day picking and packing produce, and the family lives in grower-provided housing several miles from the nearest town. She has no car and relies on a crew leader for rides. Her last clinic visit was in another state 14 months ago. She comes to a mobile clinic today because of persistent low back pain, and mentions that she sometimes feels unwell after the fields are sprayed."},
    {"id": "n525e3q046", "exam": 2, "topic": "Migrant vs rural worker", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse is explaining how migrant workers differ from rural workers who are not migrant. Which statement describes the defining difference?", "options": ["Migrant workers generally have access to care while rural workers do not", "Rural workers face poverty while migrant workers generally do not face it", "Migrant workers are employed year-round, while rural workers are seasonal workers", "Migrant workers move frequently to follow seasonal work, while rural workers stay in one location"], "correct": [3], "rationale": "A rural worker lives in one location and may have more stable employment, though with limited local jobs and resources. A migrant worker moves frequently in search of seasonal agricultural work, which creates legal, financial and social challenges and job instability. Both share a lack of access to health care from provider scarcity, poverty, limited services, lack of knowledge and social isolation.", "whyNot": ["Both groups share a lack of access to health care because of provider scarcity, poverty, limited services and social isolation.", "Poverty affects both groups and is listed among what they have in common.", "This reverses the pattern: migrant work is seasonal and unstable, and the movement follows the harvests.", ""]},
    {"id": "n525e3q047", "exam": 2, "topic": "Migrant health disparities", "type": "sata", "bloom": "Comprehension", "stem": "A nurse is planning screening for a migrant farmworker community. Which health disparities documented in this population should guide the screening plan? Select all that apply.", "options": ["Chronic conditions including hypertension, diabetes, cardiovascular disease and COPD", "Depression, anxiety and isolation", "Communicable disease including tuberculosis, HIV and parasites", "Dental disease and incomplete immunization among the children", "Lower rates of substance use than the general population", "Lower rates of domestic violence than the general population"], "correct": [0, 1, 2, 3], "rationale": "Documented health disparities among migrant farmworkers include chronic hypertension, diabetes, cardiovascular disease and COPD; mental health problems including depression, anxiety and isolation; communicable disease including tuberculosis, HIV, COVID-19, parasites and hepatitis; poor maternal health from multiple pregnancies and malnutrition; children with malnutrition, chronic infections, missing vaccinations and dental disease; and substance use and domestic violence.", "whyNot": ["", "", "", "", "Substance use is listed among the health disparities affecting this population rather than being less common.", "Domestic violence is also named among the disparities documented in migrant communities."]},
    {"id": "n525e3q048", "exam": 2, "topic": "Refugee health", "type": "mcq", "bloom": "Application", "stem": "A public health nurse is developing an intervention plan for a community with a growing refugee population. Which strategy would most effectively address this group's health care needs?", "options": ["Collaborating with interpreters and cultural mediators", "Providing written materials in English only", "Holding community health education sessions during regular working hours", "Offering free health services exclusively to refugees"], "correct": [0], "rationale": "Refugees face language and cultural barriers plus unfamiliarity with the United States health system, so collaborating with interpreters and cultural mediators is the most effective strategy. Their health risks also include trauma and post-traumatic stress, depression and anxiety, infectious disease such as tuberculosis, hepatitis B and parasites, incomplete immunizations, untreated chronic disease and malnutrition.", "whyNot": ["", "English-only material excludes the people the plan is meant to serve and ignores the language barrier that defines their access problem.", "Scheduling during work hours forces refugees to choose between income and health education.", "Exclusive services can isolate the group and generate resentment without solving the language and cultural barriers."]},
    {"id": "n525e3q049", "exam": 2, "topic": "Refugee definition", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse is explaining to a community group what distinguishes a refugee from other immigrants. Which statement is accurate?", "options": ["A refugee is any person who enters another country without proper documentation", "A refugee has fled their country because of persecution, war or violence and cannot safely return", "A refugee is a person who relocates seasonally in order to follow available work", "A refugee is a person admitted for employment in a designated shortage occupation"], "correct": [1], "rationale": "A refugee has fled their country because of persecution, war or violence and cannot safely return. That inability to return safely distinguishes refugees from migrants whose movement is driven by work, and shapes the trauma-related health risks the nurse screens for.", "whyNot": ["This describes undocumented status, which is a legal category unrelated to having fled persecution or war.", "", "This describes a migrant worker, whose movement follows employment rather than danger.", "This describes an employment-based immigration pathway, not flight from persecution."]},
    {"id": "n525e3q050", "exam": 2, "topic": "Interpreter use", "type": "mcq", "bloom": "Application", "stem": "A client who speaks little English arrives at the clinic with her adult son, who offers to interpret for the visit. Which action should the nurse take?", "options": ["Allow the son to interpret since he knows her history well", "Proceed in English slowly and use gestures to convey the key points", "Arrange a qualified interpreter and explain why one is being used", "Reschedule the visit for a day when a bilingual provider is available"], "correct": [2], "rationale": "Culturally competent care for clients with limited English requires qualified interpreters rather than family members. Using a professional interpreter protects accuracy and privacy, and should be paired with assessing the client's health values, beliefs and practices and planning follow-up that works with the client's circumstances.", "whyNot": ["Family members are specifically excluded as interpreters; they may filter, omit or reinterpret information, and the client loses privacy.", "This risks serious misunderstanding of clinical information and does not meet the standard for culturally competent care.", "", "Delaying care is unnecessary when interpretation can be arranged, and adds a second trip the client may not be able to make."]},
    {"id": "n525e3q051", "exam": 3, "topic": "Scope of ATOD problems", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse is introducing a community program on alcohol, tobacco and other drug problems. Which statement accurately describes the scope of these problems?", "options": ["They are a serious problem, but their effects are largely confined to the person who uses them", "They rank behind cardiovascular disease and cancer as a national health problem overall", "They are declining in importance as prescription drug monitoring programs expand", "They are the number-one national health problem, and the user is a risk to self, family, coworkers and community"], "correct": [3], "rationale": "Alcohol, tobacco and other drug problems are the number-one national health problem, and the person who uses is a risk to self and also to family, coworkers and the community. The preferred wording has shifted from substance abuse to alcohol, tobacco and other drug problems.", "whyNot": ["The material stresses that the user is a risk to family, coworkers and the wider community as well as to self.", "Alcohol, tobacco and other drug problems are identified as the number-one national health problem.", "Nothing in the material describes a decline; substance problems remain the leading national health problem.", ""]},
    {"id": "n525e3q052", "exam": 3, "topic": "Drug, set and setting", "type": "mcq", "bloom": "Analysis", "stem": "A nurse is analyzing why substance use is high among young adults in one neighborhood where drugs are readily available, many residents are unemployed, and use is common at social gatherings. Which framework best organizes these contributing factors?", "options": ["Drug, set and setting", "Host, agent and environment", "Primary, secondary and tertiary prevention", "Mitigation, preparedness and response"], "correct": [0], "rationale": "Contributing factors for substance use are organized as drug, meaning availability and addictive potential; set, meaning the individual using it; and setting, meaning the physical, social and cultural environment where use occurs. Genetics also contributes. Availability maps to drug, the individual residents to set, and the social gatherings and neighborhood conditions to setting.", "whyNot": ["", "The epidemiologic triad is applied to occupational health in this material; the framework named for substance use is drug, set and setting.", "This classifies interventions by when they occur, not the factors that contribute to use.", "These are phases of the disaster management cycle and do not describe contributors to substance use."]},
    {"id": "n525e3q053", "exam": 3, "topic": "Tolerance, dependence and withdrawal", "type": "mcq", "bloom": "Analysis", "stem": "A client reports that over several months he has needed progressively larger amounts of a drug to get the same effect, and that when he stops he becomes physically ill. How should the nurse describe these two findings?", "options": ["Addiction and psychological dependence", "Tolerance and physical dependence", "Withdrawal and substance misuse", "Substance use and tolerance"], "correct": [1], "rationale": "Tolerance is needing an increased dose for the same effect, and it develops quickly with nicotine and heroin. Drug dependence occurs when the body adapts to the drug so that withdrawal symptoms appear when it is stopped or reduced; withdrawal symptoms are often the opposite of the drug's effects.", "whyNot": ["Addiction is compulsive use despite harm with loss of control and craving, and psychological dependence is emotional craving; neither names the dose escalation and physical illness described.", "", "Withdrawal names only the symptoms on stopping, and misuse describes harmful or non-prescribed use, so neither accounts for the increasing dose requirement.", "Substance use alone simply means taking a psychoactive substance and does not capture becoming physically ill on stopping."]},
    {"id": "n525e3q054", "exam": 3, "topic": "Psychoactive drug categories", "type": "mcq", "bloom": "Application", "stem": "A client is brought in after using a substance. Assessment shows decreased heart rate, decreased respiratory rate, poor coordination and dulled senses, progressing toward deep sleep. Which drug category do these effects indicate?", "options": ["Stimulants", "Hallucinogens", "Depressants", "Inhalants"], "correct": [2], "rationale": "Depressants decrease central nervous system activity: lower heart rate and respiratory rate, reduced coordination and energy, dulled senses, and at high dose sleep, coma and death. Examples include alcohol, barbiturates, benzodiazepines and opioids such as heroin.", "whyNot": ["Stimulants increase central nervous system activity and wakefulness and release noradrenaline, producing the opposite picture.", "Hallucinogens stimulate the central nervous system and alter perception and mood rather than depressing vital functions toward sleep.", "", "Inhalants are short-acting with rapid onset and slight stimulation before loss of consciousness, and are typically used by young children."]},
    {"id": "n525e3q055", "exam": 3, "topic": "Stimulants", "type": "mcq", "bloom": "Comprehension", "stem": "A client who uses a stimulant tells the nurse that the drug gives him extra energy to work long shifts. Which response by the nurse reflects accurate understanding of how stimulants act?", "options": ["\"Stimulants add energy to your system, which is why fatigue returns when they wear off.\"", "\"Stimulants slow your nervous system, which is why they help you concentrate.\"", "\"Stimulants work by blocking dopamine, which reduces your sense of fatigue.\"", "\"Stimulants do not supply energy; they make your body spend its own reserves faster.\""], "correct": [3], "rationale": "Stimulants increase central nervous system activity and wakefulness and release noradrenaline. The material states specifically that they do not give energy; they make the body spend its own faster. Examples include nicotine, cocaine and crack, caffeine, amphetamines and methamphetamine.", "whyNot": ["This repeats the client's misconception; stimulants do not add energy, they accelerate the use of the body's own.", "Stimulants increase central nervous system activity; slowing it describes depressants.", "Dopamine release, not blockade, is described as the basis of addiction to stimulants such as cocaine.", ""]},
    {"id": "n525e3q056", "exam": 3, "topic": "Inhalants", "type": "mcq", "bloom": "Analysis", "stem": "A school nurse is concerned about substance use among elementary and middle school students and notes declining school performance in several children. Which substance category is most important to include in the assessment for this age group?", "options": ["Inhalants such as household chemicals and aerosols", "Hallucinogens such as LSD and MDMA", "Barbiturates obtained by prescription", "Crack cocaine purchased in the community"], "correct": [0], "rationale": "Inhalants are often among the first drugs young children use and are linked to poor school performance. They are short-acting with rapid onset, producing slight stimulation followed by loss of consciousness, and the products are household chemicals and aerosols that are easy for children to obtain.", "whyNot": ["", "These are not identified as among the first drugs young children use, and are not tied to this age group in the material.", "Prescription depressants are not described as a characteristic first substance for young children.", "Crack is expensive and rapidly addicting but is not named as a drug young children typically begin with."]},
    {"id": "n525e3q057", "exam": 3, "topic": "Tobacco as preventable death", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse is preparing a community presentation on preventable causes of death in the United States. Which statement about tobacco should the nurse include?", "options": ["Tobacco ranks second to alcohol as a preventable cause of death", "Tobacco is the foremost preventable cause of death in the United States", "Tobacco is primarily a cosmetic concern rather than a mortality risk", "Tobacco deaths are largely limited to people who began smoking as adults"], "correct": [1], "rationale": "Tobacco is the foremost preventable cause of death in the United States, through cardiovascular disease and respiratory disease. Nicotine acts as both a stimulant and a depressant, tolerance develops quickly, and smoking habits form by age 18.", "whyNot": ["Tobacco, not alcohol, is identified as the foremost preventable cause of death.", "", "Tobacco causes cardiovascular and respiratory disease and is the leading preventable cause of death.", "Smoking habits form by age 18, so most people who die of tobacco-related disease began as adolescents."]},
    {"id": "n525e3q058", "exam": 3, "topic": "Secondhand smoke", "type": "mcq", "bloom": "Application", "stem": "A parent who smokes asks the nurse whether smoking near an open window protects the children in the home. Which information should the nurse provide about secondhand smoke?", "options": ["Secondhand smoke is harmful only to adults who already have an existing chronic lung disease", "Mainstream smoke exhaled by the smoker is the more dangerous of the two components", "Sidestream smoke makes up about 85 percent of secondhand smoke and is more dangerous than mainstream smoke", "Ventilation near an open window eliminates the risk to the other people in the home"], "correct": [2], "rationale": "Sidestream smoke, which comes from the burning end of the cigarette, makes up 85 percent of secondhand smoke and is more dangerous than mainstream smoke. Because the parent keeps smoking in the home, the children remain exposed regardless of the window.", "whyNot": ["Children are among those harmed by secondhand smoke, which is why exposure in the home matters.", "This reverses the relationship; sidestream smoke is described as more dangerous than mainstream smoke.", "", "No ventilation claim appears in the material, and the burning end continues to release sidestream smoke into the room."]},
    {"id": "n525e3q059", "exam": 3, "topic": "Severe nicotine dependence", "type": "sata", "bloom": "Analysis", "stem": "A nurse is assessing the severity of a client's nicotine dependence. Which findings indicate severe dependence? Select all that apply.", "options": ["Smoking more than one pack per day", "Smoking within five minutes of waking", "Continuing to smoke while sick", "Waking during the night to smoke", "Smoking to relieve withdrawal symptoms", "Smoking only in social settings on weekends"], "correct": [0, 1, 2, 3, 4], "rationale": "Signs of severe nicotine dependence are smoking more than one pack per day, smoking within five minutes of waking, smoking while sick, waking at night to smoke, and smoking to relieve withdrawal. These findings guide how intensive the cessation plan needs to be.", "whyNot": ["", "", "", "", "", "Occasional, situation-limited smoking is the opposite of the pattern that signals severe dependence."]},
    {"id": "n525e3q060", "exam": 3, "topic": "Smoking cessation", "type": "mcq", "bloom": "Application", "stem": "A client tells the nurse he is ready to quit smoking and asks what approach works best. Which recommendation should the nurse make?", "options": ["Abrupt cessation without medication or support, to avoid dependence on aids", "Nicotine replacement alone, with no counseling or support group", "Gradually switching to electronic cigarettes as a long-term substitute", "A combined approach pairing emotional support with medication"], "correct": [3], "rationale": "The best approach for a client ready to quit is multi-step and combined: emotional support through quit programs, Nicotine Anonymous, support groups and family and friends, together with medication such as nicotine replacement gum, patch, nasal spray or lozenge, varenicline or bupropion. The five A's structure the encounter: ask, advise, assess readiness, assist with a quit plan and quit date, and arrange follow-up.", "whyNot": ["Quitting unaided is harder and less successful; cessation medications treat dependence rather than prolonging it.", "Medication alone is less effective than pairing it with counseling and support.", "Vaping delivers highly concentrated nicotine, is not regulated like tobacco, and carries its own risks including progression back to cigarettes.", ""]},
    {"id": "n525e3q061", "exam": 3, "topic": "Vaping risks", "type": "sata", "bloom": "Comprehension", "stem": "A school nurse is preparing education for parents about electronic cigarettes. Which risks of vaping should the nurse include? Select all that apply.", "options": ["Progression to smoking conventional cigarettes", "Lung damage and injuries from the equipment", "Appeal to youth and social normalization of use", "Poisoning in young children who access the liquid", "Regulation equivalent to that applied to tobacco products", "Elimination of secondhand exposure for people nearby"], "correct": [0, 1, 2, 3], "rationale": "Electronic cigarettes are battery-heated, flavored and deliver highly concentrated nicotine, and they are not regulated like tobacco. Risks include progression to cigarettes, lung damage, equipment injuries, appeal to youth, social normalization, poisoning in children, secondhand vapor and increased COVID-19 risk. The public often does not perceive vaping as smoking.", "whyNot": ["", "", "", "", "Vaping products are described as not regulated like tobacco, which is part of the concern rather than a risk of use.", "Secondhand vapor is listed among the risks, so exposure to others is not eliminated."]},
    {"id": "n525e3q062", "exam": 3, "topic": "Methamphetamine assessment", "type": "sata", "bloom": "Analysis", "stem": "A nurse suspects methamphetamine use in a client seen at a community clinic. Which findings would support that suspicion? Select all that apply.", "options": ["Sudden weight loss and sweating", "Blackened, rotting and broken teeth", "Slow-healing sores and burns on the lips and fingers", "Premature aging of the skin", "Bradycardia with deep, slow respirations", "Pinpoint pupils while the client is high"], "correct": [0, 1, 2, 3], "rationale": "Methamphetamine signs include sudden weight loss, sweating, irregular breathing, nosebleeds, slow-healing sores, burns on the lips and fingers, track marks, meth mouth with blackened, rotting and broken teeth, and premature skin aging. Pupils are dilated when high and pinpoint in overdose.", "whyNot": ["", "", "", "", "Methamphetamine is a stimulant producing irregular breathing and sympathetic activation, not a slow heart rate with slow deep breathing.", "Pupils are dilated when the client is high on methamphetamine; pinpoint pupils occur in overdose."]},
    {"id": "n525e3q063", "exam": 3, "topic": "Drug paraphernalia", "type": "mcq", "bloom": "Application", "stem": "During a home visit a nurse observes scorched aluminum foil, burned spoons, rolled bills and lengths of tubing in a client's room. How should the nurse interpret this finding?", "options": ["These items are drug paraphernalia and warrant assessment for substance use", "These items confirm the client is currently in withdrawal", "These items are unrelated to substance use and need no follow-up", "These items indicate the client is selling drugs rather than using them"], "correct": [0], "rationale": "Paraphernalia associated with substance use include scorched foil, pipes, burned spoons, rolled bills and straws, glass and razor blades, syringes, and tubing or shoelaces. Recognizing them should prompt nonjudgmental assessment, screening and offers of help rather than confrontation or dismissal.", "whyNot": ["", "Paraphernalia indicate use but say nothing about whether the client is currently withdrawing, which requires clinical assessment.", "Dismissing recognized paraphernalia would miss an opportunity for screening, referral and overdose prevention.", "Nothing distinguishes use from distribution here, and the nursing concern is the client's health."]},
    {"id": "n525e3q064", "exam": 3, "topic": "Neurobiology of addiction", "type": "mcq", "bloom": "Analysis", "stem": "A family member asks the nurse why her relative cannot simply choose to stop using methamphetamine when natural rewards such as food no longer interest him. Which explanation is most accurate?", "options": ["He has permanently lost the ability to experience any kind of pleasure", "Methamphetamine releases far more dopamine than natural rewards, so ordinary pleasures no longer compete", "His behavior reflects a simple lack of willpower rather than any change in the brain itself", "Natural rewards release more dopamine but act far too slowly to be noticed"], "correct": [1], "rationale": "Dopamine release relative to baseline is about 150 percent for food, 200 percent for sex, 350 percent for cocaine, roughly 700 percent for heroin and 1200 percent for methamphetamine, so natural rewards cannot compete. Addiction is a chronic, relapsing brain disease with compulsive use despite harm, loss of control and craving, and brain function recovers with prolonged abstinence.", "whyNot": ["Brain function recovers with prolonged abstinence, partially at one month and much more by fourteen months.", "", "Addiction is described as a chronic, relapsing brain disease, not a failure of will.", "This reverses the relationship; drugs release substantially more dopamine than food or sex."]},
    {"id": "n525e3q065", "exam": 3, "topic": "Cycle of addiction", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse is teaching about the three stages that repeat in the cycle of addiction. Which sequence should the nurse describe?", "options": ["Tolerance, physical dependence, and eventual permanent remission of use", "Experimentation, regular use, and eventual spontaneous recovery", "Binge and intoxication, withdrawal and negative affect, preoccupation and anticipation", "Craving, sustained abstinence, and complete neurologic recovery"], "correct": [2], "rationale": "The cycle of addiction moves through binge and intoxication, then withdrawal and negative affect, then preoccupation and anticipation, which leads back into use. Understanding the cycle helps the nurse anticipate when relapse risk is highest and target support accordingly.", "whyNot": ["These are separate concepts about how the body adapts, and permanent remission is not a stage of the addiction cycle.", "This describes a progression of use rather than the named three-stage cycle.", "", "Recovery of brain function occurs over prolonged abstinence but is not one of the three repeating stages."]},
    {"id": "n525e3q066", "exam": 3, "topic": "Enabling behavior", "type": "mcq", "bloom": "Analysis", "stem": "Before the emergency occurs, the nurse considers the mother's description of calling Danny's employer and paying his overdue rent. How should the nurse interpret these behaviors?", "options": ["They are appropriate supports that demonstrate a healthy family response", "They indicate the mother is also using substances herself", "They show the mother has accepted that her son has a substance use problem", "They are enabling behaviors that shield him from consequences so use can continue"], "correct": [3], "rationale": "An enabler is a family member or friend who, often unknowingly, protects the person who uses from consequences so the use continues: calling in sick for them, making excuses, paying their debts or bail, buying alcohol, cleaning up after them and denying the problem. Enabling is related to codependency, and families should be referred to Al-Anon or Alateen.", "whyNot": ["Protecting the person from consequences allows continued use and is distinguished from genuine support in the material.", "Nothing in the scenario suggests the mother uses substances; her behavior pattern is enabling, which is distinct.", "Enabling often coexists with denial of the problem, and these specific acts protect him from its consequences.", ""], "caseId": "c3danny", "caseTitle": "Case 3 - A home visit in Worcester", "scenario": "A community health nurse is making a home visit to a family in Worcester. The client's 27-year-old son, Danny, has a history of opioid use disorder and was discharged from a detoxification program three weeks ago. During the visit his mother says she has been calling his employer to report him sick on days he cannot get up, and has twice paid his overdue rent so he would not be evicted. While the nurse is still in the home, the mother calls out that Danny will not wake up. The nurse finds him unresponsive on his bed, with slow, shallow breathing, pinpoint pupils, and bluish lips."},
    {"id": "n525e3q067", "exam": 3, "topic": "Opioid overdose recognition", "type": "sata", "bloom": "Analysis", "stem": "The nurse assesses Danny on the bed. Which of the nurse's findings are recognized signs of opioid overdose? Select all that apply.", "options": ["Unresponsiveness and inability to wake him", "Slow, shallow breathing", "Pinpoint pupils", "Bluish discoloration of the lips", "Dilated pupils with rapid, deep respirations", "Flushed, warm, dry skin with a bounding pulse"], "correct": [0, 1, 2, 3], "rationale": "Signs of opioid overdose include being unresponsive or not waking; slow, shallow or absent breathing; pinpoint pupils; blue or gray lips and fingernails; gurgling or snoring sounds; pale, clammy skin; and a limp body. Danny shows four of these simultaneously.", "whyNot": ["", "", "", "", "This pattern suggests stimulant effect rather than opioid overdose, in which pupils constrict and respirations slow.", "Opioid overdose produces pale, clammy skin rather than warm, flushed, dry skin."], "caseId": "c3danny", "caseTitle": "Case 3 - A home visit in Worcester", "scenario": "A community health nurse is making a home visit to a family in Worcester. The client's 27-year-old son, Danny, has a history of opioid use disorder and was discharged from a detoxification program three weeks ago. During the visit his mother says she has been calling his employer to report him sick on days he cannot get up, and has twice paid his overdue rent so he would not be evicted. While the nurse is still in the home, the mother calls out that Danny will not wake up. The nurse finds him unresponsive on his bed, with slow, shallow breathing, pinpoint pupils, and bluish lips."},
    {"id": "n525e3q068", "exam": 3, "topic": "Naloxone administration", "type": "mcq", "bloom": "Application", "stem": "The nurse confirms Danny is unresponsive and not breathing adequately. Nasal naloxone is available in the home. Which action should the nurse take first?", "options": ["Call 911 while beginning the overdose response", "Administer the nasal naloxone and then wait to see whether he responds", "Place him in the recovery position and monitor his breathing", "Ask the mother what and how much he took before acting"], "correct": [0], "rationale": "The naloxone sequence begins with checking responsiveness by shouting and using a sternal rub and calling 911, then laying the person on the back with the head tilted back, inserting the nozzle in a nostril and pressing the plunger, giving rescue breaths or placing the person in the recovery position, repeating in the other nostril if there is no response in two to three minutes, and staying with the person.", "whyNot": ["", "Naloxone is given promptly, but emergency services must be activated because naloxone can wear off before the opioid does.", "Positioning follows naloxone and rescue breathing; it does not reverse the respiratory depression that is killing him.", "Gathering a history delays reversal of life-threatening respiratory depression in a patient who is already unresponsive."], "caseId": "c3danny", "caseTitle": "Case 3 - A home visit in Worcester", "scenario": "A community health nurse is making a home visit to a family in Worcester. The client's 27-year-old son, Danny, has a history of opioid use disorder and was discharged from a detoxification program three weeks ago. During the visit his mother says she has been calling his employer to report him sick on days he cannot get up, and has twice paid his overdue rent so he would not be evicted. While the nurse is still in the home, the mother calls out that Danny will not wake up. The nurse finds him unresponsive on his bed, with slow, shallow breathing, pinpoint pupils, and bluish lips."},
    {"id": "n525e3q069", "exam": 3, "topic": "Naloxone follow-up", "type": "mcq", "bloom": "Analysis", "stem": "Danny begins breathing and opens his eyes about three minutes after naloxone is given. He is agitated and says he feels sick and wants everyone to leave. Which nursing action is most important?", "options": ["Document the response and end the visit since the naloxone worked", "Stay with him and keep emergency services involved, because the overdose can return", "Give a second dose of naloxone now that he is awake and agitated", "Explain that his agitation means he received too much naloxone"], "correct": [1], "rationale": "Naloxone can wear off before the opioid does, so the overdose can return, and it may cause acute withdrawal with agitation and vomiting. Staying with the person and ensuring emergency services transport and observe him addresses both the risk of recurrence and the discomfort of precipitated withdrawal.", "whyNot": ["Leaving is unsafe because naloxone can wear off before the opioid, allowing the overdose to recur.", "", "A repeat dose is indicated when there is no response in two to three minutes, not after breathing has been restored.", "Agitation and vomiting reflect acute withdrawal precipitated by naloxone, which is an expected effect rather than evidence of overdose of the antidote."], "caseId": "c3danny", "caseTitle": "Case 3 - A home visit in Worcester", "scenario": "A community health nurse is making a home visit to a family in Worcester. The client's 27-year-old son, Danny, has a history of opioid use disorder and was discharged from a detoxification program three weeks ago. During the visit his mother says she has been calling his employer to report him sick on days he cannot get up, and has twice paid his overdue rent so he would not be evicted. While the nurse is still in the home, the mother calls out that Danny will not wake up. The nurse finds him unresponsive on his bed, with slow, shallow breathing, pinpoint pupils, and bluish lips."},
    {"id": "n525e3q070", "exam": 3, "topic": "Family referral and codependency", "type": "mcq", "bloom": "Application", "stem": "After Danny is transported, his mother tells the nurse she feels responsible and does not know how to help him without making things worse. Which referral is most appropriate for her?", "options": ["Narcotics Anonymous", "Nicotine Anonymous", "Al-Anon", "A detoxification program"], "correct": [2], "rationale": "Al-Anon supports family members and friends of people with alcohol and drug problems, and Alateen serves teenagers in those families. Enabling is related to codependency, and the material directs nurses to refer the family to Al-Anon or Alateen. Narcotics Anonymous and detoxification serve the person who uses the substance.", "whyNot": ["Narcotics Anonymous is a support group for the person who uses drugs, not for family members.", "This group supports people quitting tobacco and does not address her situation.", "", "Detoxification treats physical dependence in the person who uses the substance; the mother does not need detoxification."], "caseId": "c3danny", "caseTitle": "Case 3 - A home visit in Worcester", "scenario": "A community health nurse is making a home visit to a family in Worcester. The client's 27-year-old son, Danny, has a history of opioid use disorder and was discharged from a detoxification program three weeks ago. During the visit his mother says she has been calling his employer to report him sick on days he cannot get up, and has twice paid his overdue rent so he would not be evicted. While the nurse is still in the home, the mother calls out that Danny will not wake up. The nurse finds him unresponsive on his bed, with slow, shallow breathing, pinpoint pupils, and bluish lips."},
    {"id": "n525e3q071", "exam": 3, "topic": "Harm reduction", "type": "mcq", "bloom": "Application", "stem": "The nurse plans to leave naloxone and fentanyl test strips with the family and teach them how to use both, even though Danny has not agreed to stop using. Which approach does this reflect?", "options": ["Enabling, because supplies are provided while the person continues to use", "Tertiary prevention, because the substance use disorder already exists", "A contingency plan that applies only after a client agrees to enter treatment", "Harm reduction, which meets people where they are to reduce death and disease"], "correct": [3], "rationale": "Harm reduction recognizes that addiction is a health problem, that any psychoactive drug can be abused, that accurate information helps people make responsible decisions, and that people with these problems can be helped; its focus is education. It meets people where they are and reduces death and disease even if use continues. Examples include naloxone distribution, syringe service programs, fentanyl test strips, designated drivers, and medications for opioid use disorder such as methadone and buprenorphine.", "whyNot": ["Enabling shields the person from consequences; harm reduction reduces death and disease and is an evidence-based public health approach.", "Harm reduction here prevents a fatal overdose that has not happened, and the material frames its focus as education.", "Harm reduction specifically does not require abstinence or a treatment commitment as a condition.", ""], "caseId": "c3danny", "caseTitle": "Case 3 - A home visit in Worcester", "scenario": "A community health nurse is making a home visit to a family in Worcester. The client's 27-year-old son, Danny, has a history of opioid use disorder and was discharged from a detoxification program three weeks ago. During the visit his mother says she has been calling his employer to report him sick on days he cannot get up, and has twice paid his overdue rent so he would not be evicted. While the nurse is still in the home, the mother calls out that Danny will not wake up. The nurse finds him unresponsive on his bed, with slow, shallow breathing, pinpoint pupils, and bluish lips."},
    {"id": "n525e3q072", "exam": 3, "topic": "ATOD primary prevention", "type": "sata", "bloom": "Application", "stem": "A community health nurse is planning primary prevention for substance use in a middle school. Which interventions belong at this level? Select all that apply.", "options": ["Teaching assertiveness and decision-making skills", "Teaching stress reduction and relaxation techniques", "Drug education explaining that no drug is completely safe and any drug can be abused", "Promoting healthy lifestyles and building resiliency", "Drug testing students who are identified as high risk", "Referring students who use substances to a treatment program"], "correct": [0, 1, 2, 3], "rationale": "Primary prevention for substance use promotes healthy lifestyles and resiliency; teaches assertiveness, decision-making, stress reduction and relaxation; and provides drug education emphasizing that no drug is completely safe and any drug can be abused, helping people make informed decisions to minimize harm.", "whyNot": ["", "", "", "", "Testing to detect a problem early is secondary prevention.", "Referral to treatment for an existing problem is tertiary prevention."]},
    {"id": "n525e3q073", "exam": 3, "topic": "ATOD secondary prevention", "type": "mcq", "bloom": "Application", "stem": "A nurse at a community health center screens pregnant clients, older adults and people who inject drugs for substance use problems. Which level of prevention do these activities represent?", "options": ["Secondary prevention", "Primary prevention", "Tertiary prevention", "Quaternary prevention"], "correct": [0], "rationale": "Secondary prevention for substance problems means assessing and screening, including drug testing, with a focus on high-risk groups: adolescents, older adults, people who inject drugs, pregnant women and people using illicit drugs. It also addresses codependency and family involvement.", "whyNot": ["", "Primary prevention would be education and skill-building before a problem develops, not screening to detect one.", "Tertiary prevention includes detoxification, treatment and support groups for an existing problem.", "This level is not part of the framework used in this material, which uses primary, secondary and tertiary."]},
    {"id": "n525e3q074", "exam": 3, "topic": "ATOD tertiary prevention", "type": "sata", "bloom": "Application", "stem": "A nurse is identifying tertiary prevention resources for clients with established substance use problems. Which resources belong at this level? Select all that apply.", "options": ["Detoxification and addiction treatment programs", "Alcoholics Anonymous and Narcotics Anonymous", "Smoking-cessation programs", "Al-Anon and Alateen for family members", "Classroom drug education for sixth-grade students", "Routine drug testing of workers in a high-risk industry"], "correct": [0, 1, 2, 3], "rationale": "Tertiary prevention for substance problems includes detoxification, addiction treatment, smoking-cessation programs and support groups such as Alcoholics Anonymous, Al-Anon and Alateen for family and teens, Narcotics Anonymous, Pills Anonymous, and Overeaters and Gamblers Anonymous.", "whyNot": ["", "", "", "", "Education before a problem develops is primary prevention.", "Testing to detect problems early is secondary prevention."]},
    {"id": "n525e3q075", "exam": 3, "topic": "Nurse's attitudes toward substance use", "type": "mcq", "bloom": "Application", "stem": "A nurse notices feeling frustrated with clients who return to substance use after treatment and is aware that this feeling affects interactions. Which action should the nurse take first?", "options": ["Request reassignment to a population without substance use problems", "Examine personal attitudes and beliefs about alcohol and drug problems", "Set stricter conditions that clients must meet to remain in the program", "Focus education on the consequences of relapse for the client's family"], "correct": [1], "rationale": "Every culture labels drugs as good or bad, which shapes attitudes, and the material directs nurses always to examine their own attitudes. Addiction is a chronic, relapsing brain disease, so return to use is part of the illness rather than evidence of a failure that justifies harsher treatment.", "whyNot": ["Avoidance does not resolve the bias, and substance problems affect clients in every community setting.", "", "Imposing conditions out of frustration punishes relapse, which is an expected feature of a chronic, relapsing disease.", "Emphasizing consequences in this frame risks shaming the client and reflects the nurse's frustration rather than an assessed need."]},
    {"id": "n525e3q076", "exam": 4, "topic": "Purpose of family violence", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse is teaching a class about family violence and is asked what drives the behavior of a person who abuses a family member. Which response identifies the underlying purpose?", "options": ["To release stress accumulated from work and financial pressure", "To discipline family members whose behavior is unacceptable", "To gain and maintain total control over the victim", "To respond to provocation by the person who is harmed"], "correct": [2], "rationale": "The purpose of family violence is to gain and maintain total control over the victim. Keeping this in view helps the nurse understand why abuse escalates when the victim seeks independence and why safety planning is central.", "whyNot": ["Work stress and economic downturns can spill into the home, but they are contributing conditions rather than the purpose of the violence.", "Framing violence as discipline adopts the perpetrator's justification and obscures the control that actually motivates it.", "", "This places responsibility on the victim and misrepresents the dynamic, which originates with the person who abuses."]},
    {"id": "n525e3q077", "exam": 4, "topic": "Violence statistics", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse is preparing a presentation on violence as a public health problem affecting young people. Which statement reflects the data presented in the course material?", "options": ["Unintentional injury is now the only significant cause of death for these two age groups", "Violent death among young people has become quite rare in the United States", "Violence against health care workers has steadily declined in recent years", "Suicide was the second leading cause of death for ages 10 to 24 and homicide the third for ages 15 to 24"], "correct": [3], "rationale": "In 2017 suicide was the second leading cause of death for ages 10 to 24 and homicide the third for ages 15 to 24. Interpersonal violence, including community, intimate partner and sexual violence, together with suicide, are the most severe forms. Nurses care for victims, perpetrators and witnesses, and violence against health care workers is increasing.", "whyNot": ["Unintentional injury is important, but suicide and homicide rank among the leading causes for these ages.", "Interpersonal violence and suicide are identified as among the most severe forms of violence affecting this population.", "The material states that violence against health care workers is increasing.", ""]},
    {"id": "n525e3q078", "exam": 4, "topic": "Abuse versus neglect", "type": "mcq", "bloom": "Analysis", "stem": "A school nurse sees a 7-year-old who is significantly underweight, has poor hygiene, wears clothing inappropriate for the weather, and has missed many school days. How should the nurse classify these findings?", "options": ["Possible neglect, which is an act of omission", "Possible physical abuse, which is an act of commission", "Possible emotional abuse through verbal degradation", "Normal variation that requires no further assessment"], "correct": [0], "rationale": "Abuse is an act of commission, meaning doing harm such as hitting, sexual contact or verbal degradation. Neglect is an act of omission, meaning failure to provide food, shelter, supervision, education, medical or dental care, or hygiene. Neglect is identified by being underweight or failing to thrive, poor hygiene, untreated conditions, missed school and inappropriate clothing.", "whyNot": ["", "Physical abuse involves doing harm, such as hitting; these findings reflect care that was not provided.", "Emotional abuse involves degrading or demeaning communication, which is not what these physical findings describe.", "Underweight, poor hygiene, untreated conditions and missed school are the listed indicators of neglect and require follow-up."]},
    {"id": "n525e3q079", "exam": 4, "topic": "Classifying maltreatment", "type": "mcq", "bloom": "Analysis", "stem": "A parent repeatedly tells a child in front of the nurse, \"You are no good and you will never amount to anything.\" How should the nurse classify this behavior?", "options": ["Emotional neglect", "Emotional abuse", "Educational neglect", "Appropriate parental discipline"], "correct": [1], "rationale": "Verbal degradation is an act of commission and therefore abuse, specifically emotional abuse. Educational neglect would be an omission such as keeping a child home from school for two weeks to babysit, and physical neglect would be failing to provide food, hygiene or medical care.", "whyNot": ["Neglect is a failure to provide something the child needs; this is an active, degrading communication directed at the child.", "", "Educational neglect involves failing to ensure the child receives schooling, such as keeping a child home to babysit.", "Degrading a child is not discipline; it is a recognized form of emotional abuse."]},
    {"id": "n525e3q080", "exam": 4, "topic": "Children at higher risk for abuse", "type": "sata", "bloom": "Analysis", "stem": "A nurse is identifying children at increased risk for abuse and neglect in a community caseload. Which characteristics increase risk? Select all that apply.", "options": ["Being younger than four years of age", "Having a disability, chronic illness or special needs", "Living in a family experiencing poverty", "Having a parent with substance use or mental illness", "Living in a home where intimate partner violence occurs", "Having several older siblings living in the same household"], "correct": [0, 1, 2, 3, 4], "rationale": "Children at higher risk include infants and young children under four, those born premature or at low birth weight, those with disabilities, chronic illness or special needs, those with a difficult temperament, children of unwanted pregnancies, a child who is not the biological child of the mother's partner, families in poverty, parental substance use or mental illness, intimate partner violence in the home, and social isolation. Children in poverty have about five times higher rates of abuse and neglect.", "whyNot": ["", "", "", "", "", "Having older siblings is not listed among the risk characteristics; social isolation of the family is the relevant concern."]},
    {"id": "n525e3q081", "exam": 4, "topic": "Development of abusive patterns", "type": "mcq", "bloom": "Analysis", "stem": "A nurse assesses a father who was physically abused as a child, is highly critical of his toddler, and expects the child to behave like a much older child. Which analysis is most accurate?", "options": ["Having been abused as a child makes future abuse essentially certain", "Unrealistic expectations alone are reassuring because they show involvement", "Previous exposure to violence and unrealistic expectations together raise the risk of abuse", "His history is irrelevant now that he is an adult with his own family"], "correct": [2], "rationale": "A history of child abuse in the person who abuses is a learned pattern, often with a hostile, verbally aggressive style from parents who set unrealistic goals, criticized, punished and withheld affection. Previous exposure to violence strongly predicts future violence. The cycle runs from unrealistic expectations to unmet needs to frustration and intolerance to aggressive, overly critical feelings.", "whyNot": ["Prior exposure strongly predicts future violence but is a risk factor, not a certainty, and framing it as inevitable removes the reason to intervene.", "Unrealistic expectations are a specific red flag, because the child cannot meet them and frustration follows.", "", "Abusive behavior is described as learned, so a parental history of being abused remains an important part of the assessment."]},
    {"id": "n525e3q082", "exam": 4, "topic": "Intimate partner violence assessment", "type": "mcq", "bloom": "Application", "stem": "A nurse suspects that a woman being examined for an injury is being physically abused by her partner, who is in the waiting room. Which action should the nurse take first?", "options": ["Ask the partner to describe how the injury occurred", "Tell her she must leave the relationship for her own safety", "Report the suspected abuse to the police before speaking with her", "Interview her privately and ask directly whether someone hurt her"], "correct": [3], "rationale": "Intimate partner violence is screened in private, speaking directly to the patient and asking direct questions such as whether someone is hurting her and whether she feels safe at home. The nurse believes and supports her, assesses immediate safety, documents objectively, develops a safety and escape plan, and provides resources. Whether to leave is her decision.", "whyNot": ["Asking the suspected abuser allows him to control the account and puts the patient at further risk.", "The decision whether to leave is hers; directing her may end her engagement and can increase danger.", "A competent adult experiencing intimate partner violence is generally not a mandated report, and acting without her is a breach of autonomy.", ""]},
    {"id": "n525e3q083", "exam": 4, "topic": "Mandatory reporting: child", "type": "mcq", "bloom": "Application", "stem": "A nurse in Massachusetts has reasonable cause to believe that a 6-year-old patient is being abused at home, but has no proof. Which action should the nurse take?", "options": ["Report immediately to the Department of Children and Families", "Gather additional evidence before deciding whether to report", "Notify the parents of the concern and observe at the next visit", "Report only if the child states directly that a parent caused the injury"], "correct": [0], "rationale": "Mandated reporters must report immediately, orally or in writing, when they have reasonable cause to believe abuse or neglect has occurred; proof is not required, and a written report follows within 48 hours. The reporter is protected from civil and criminal liability. Willful failure to report that results in serious injury or death carries a fine up to $5,000 and up to two and a half years in jail. The nurse reports; the nurse does not investigate.", "whyNot": ["", "Mandated reporters report on reasonable cause; proof is not required and investigating is not the nurse's role.", "Alerting the family can place the child at greater risk and delays the protective response.", "Reasonable suspicion is the threshold, and children often do not disclose, so waiting for a statement leaves the child unprotected."]},
    {"id": "n525e3q084", "exam": 4, "topic": "Mandatory reporting: adults", "type": "mcq", "bloom": "Application", "stem": "A home health nurse in Massachusetts is concerned about three clients: a 72-year-old whose adult child is taking her money, a 45-year-old with an intellectual disability whose caregiver leaves him unattended for long periods, and a 35-year-old competent woman whose partner struck her. Which reporting plan is correct?", "options": ["Report all three of these clients to the Department of Children and Families for a single investigation", "Report the 72-year-old to Elder Protective Services and the 45-year-old to the Disabled Persons Protection Commission", "Report only the 35-year-old to the police, because she is the one with a physical injury", "Report none of them, because mandated reporting in Massachusetts applies only to children"], "correct": [1], "rationale": "In Massachusetts, abuse of a child under 18 is reported to the Department of Children and Families, elders aged 60 and older to Elder Protective Services including financial exploitation, and disabled adults aged 18 to 59 to the Disabled Persons Protection Commission. For a competent adult experiencing intimate partner violence the nurse is generally not mandated to report and instead asks, supports, safety plans, provides resources and respects autonomy, though Massachusetts does require reporting gunshot and stab wounds and serious burns to police.", "whyNot": ["That agency receives reports about children under 18; none of these three clients is a child.", "", "A competent adult experiencing intimate partner violence is generally not a mandated report, while the other two situations are.", "Elder abuse and abuse of a disabled adult are both mandated reports in Massachusetts."]},
    {"id": "n525e3q085", "exam": 4, "topic": "Suicide risk assessment", "type": "sata", "bloom": "Application", "stem": "A nurse is assessing a client who has expressed hopelessness. Which questions should the nurse ask to evaluate suicide risk? Select all that apply.", "options": ["\"Do you want to hurt yourself?\"", "\"Do you have a plan?\"", "\"Do you have the means to carry out that plan?\"", "\"Have you ever tried to hurt yourself before?\"", "\"You would not really do anything, would you?\"", "\"Let's talk about something more positive instead.\""], "correct": [0, 1, 2, 3], "rationale": "Suicide assessment asks directly about ideation, a plan, the means, and prior attempts. Asking directly does not plant the idea and is necessary to establish risk. Suicide occurs about once every 16 minutes; women attempt more often and men complete more often, being about four times more likely to use firearms, and the highest-risk age group is 65 and older.", "whyNot": ["", "", "", "", "A leading question invites denial and signals that the nurse does not want to hear the truth.", "Changing the subject avoids the assessment and leaves genuine risk undetected."]},
    {"id": "n525e3q086", "exam": 4, "topic": "Sexual assault", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse is teaching about sexual assault in the community. Which statement reflects the information presented?", "options": ["Most assaults are committed by a stranger who was unknown to the victim, usually in a public place", "Nearly all sexual assaults are reported to law enforcement, so the official counts are accurate", "It is the most underreported violent crime, and more than half of assaults are by a relative, friend or acquaintance", "Assault rates are higher in rural areas than urban areas, and highest during weekday mornings"], "correct": [2], "rationale": "Sexual assault affects about one in six women and one in thirty-three men for attempted or completed assault, is the most underreported violent crime with only about one third reported, and more than half are committed by a relative, friend or acquaintance. Rates are higher in urban than rural areas, and higher between 8 pm and 2 am, on weekends and in summer. Nursing care is nonjudgmental with forensic referral and support.", "whyNot": ["More than half are committed by a relative, friend or acquaintance, which is part of why reporting is low.", "Only about one third are reported, making it the most underreported violent crime.", "", "The material describes urban rates as higher than rural."]},
    {"id": "n525e3q087", "exam": 4, "topic": "Human trafficking: recognition", "type": "sata", "bloom": "Analysis", "stem": "Which findings in this encounter should raise the nurse's suspicion for human trafficking? Select all that apply.", "options": ["The companion answers questions that are directed to the patient", "She has bruises in various stages of healing", "She appears malnourished", "Her identification documents are held by another person", "The companion controls how long the visit may last", "The patient was brought to the clinic rather than coming alone"], "correct": [0, 1, 2, 3, 4], "rationale": "Trafficking signs include a companion who will not let the patient answer, unexplained bruises, burns or bites, genital tearing, sexually transmitted infections, unintended pregnancy, malnutrition, substance use, depression, post-traumatic stress and suicidality. Traffickers often arrive posing as family or a friend, and control of identification documents is a recognized means of coercion.", "whyNot": ["", "", "", "", "", "Arriving with another person is common and not suspicious by itself; the concern is the companion's control over her."], "caseId": "c4traffic", "caseTitle": "Case 4 - A clinic visit with a companion", "scenario": "A 19-year-old woman is brought to a community clinic by a man who says he is her cousin. He stays beside her, answers questions directed to her, and says they cannot stay long. The woman avoids eye contact, appears underweight, and has bruising on both upper arms in various stages of healing. She has no identification and gives an address the man corrects. When the nurse asks about her living situation, the man says she lives with several other young women who work with him and that he holds their documents for safekeeping."},
    {"id": "n525e3q088", "exam": 4, "topic": "Human trafficking: interviewing", "type": "mcq", "bloom": "Application", "stem": "The nurse wants to speak with the patient about her situation. The companion states he prefers to stay with her. Which action should the nurse take?", "options": ["Ask the companion directly to leave because trafficking is suspected", "Interview her with the companion present but ask the questions quickly", "Ask the companion to interpret the sensitive questions for her", "Give a routine reason, such as needing an x-ray, to separate them and interview her alone"], "correct": [3], "rationale": "The patient must be interviewed alone, and the material directs the nurse to give a reason such as needing a laboratory test or x-ray so the separation appears routine. This may be one of very few chances she has to disclose or escape, so it must not alert the companion. A professional interpreter is used if one is needed.", "whyNot": ["Naming the suspicion alerts a possible trafficker, which can end the visit abruptly and endanger her.", "She cannot answer honestly in front of someone who controls her, so the information obtained would be unreliable.", "A companion must never serve as interpreter, least of all one who may be the person exploiting her.", ""], "caseId": "c4traffic", "caseTitle": "Case 4 - A clinic visit with a companion", "scenario": "A 19-year-old woman is brought to a community clinic by a man who says he is her cousin. He stays beside her, answers questions directed to her, and says they cannot stay long. The woman avoids eye contact, appears underweight, and has bruising on both upper arms in various stages of healing. She has no identification and gives an address the man corrects. When the nurse asks about her living situation, the man says she lives with several other young women who work with him and that he holds their documents for safekeeping."},
    {"id": "n525e3q089", "exam": 4, "topic": "Human trafficking: screening questions", "type": "sata", "bloom": "Application", "stem": "The nurse is now alone with the patient. Which screening questions are appropriate to assess for trafficking? Select all that apply.", "options": ["\"Can you come and go as you please?\"", "\"Has anyone harmed or threatened you for trying to leave?\"", "\"Do you have to ask permission to eat, sleep or use the bathroom?\"", "\"Has anyone taken away your identification papers?\"", "\"Are there locks that keep you from leaving?\"", "\"Why have you allowed this situation to continue?\""], "correct": [0, 1, 2, 3, 4], "rationale": "Trafficking screening asks whether the person can come and go as they please, whether anyone has harmed or threatened them for trying to leave, whether they are forced to do things, whether they must ask permission to eat, sleep or use the bathroom, whether locks keep them in, whether they have been denied food, water, sleep or medical care, whether threats have been made against family, and whether identification papers have been taken.", "whyNot": ["", "", "", "", "", "A question phrased as blame shames the patient, implies she is responsible, and will shut down disclosure."], "caseId": "c4traffic", "caseTitle": "Case 4 - A clinic visit with a companion", "scenario": "A 19-year-old woman is brought to a community clinic by a man who says he is her cousin. He stays beside her, answers questions directed to her, and says they cannot stay long. The woman avoids eye contact, appears underweight, and has bruising on both upper arms in various stages of healing. She has no identification and gives an address the man corrects. When the nurse asks about her living situation, the man says she lives with several other young women who work with him and that he holds their documents for safekeeping."},
    {"id": "n525e3q090", "exam": 4, "topic": "Human trafficking: intervention", "type": "mcq", "bloom": "Analysis", "stem": "Alone with the nurse, the 19-year-old discloses that she cannot leave the house freely but says she is not in immediate danger today and is frightened of what will happen if anyone intervenes. Which nursing action is most appropriate?", "options": ["Involve a social worker or victim advocate and work to build trust with her", "Call the police immediately against her stated wishes", "Report the situation to the Department of Children and Families", "Discharge her with a hotline number and no further intervention"], "correct": [0], "rationale": "For a trafficking situation the nurse interviews the patient alone, uses an interpreter if needed, and involves a social worker or victim advocate. A child is reported to child protective services and an adult in immediate danger to police; otherwise the nurse builds trust, because this may be one of few chances the person has to escape.", "whyNot": ["", "Police are contacted for an adult in immediate danger; she has stated she is not, and acting against her wishes may destroy the trust that lets her reach help.", "That agency receives reports about children under 18, and this patient is 19.", "A number alone does not help someone whose movement and documents are controlled, and misses the chance to connect her to advocacy now."], "caseId": "c4traffic", "caseTitle": "Case 4 - A clinic visit with a companion", "scenario": "A 19-year-old woman is brought to a community clinic by a man who says he is her cousin. He stays beside her, answers questions directed to her, and says they cannot stay long. The woman avoids eye contact, appears underweight, and has bruising on both upper arms in various stages of healing. She has no identification and gives an address the man corrects. When the nurse asks about her living situation, the man says she lives with several other young women who work with him and that he holds their documents for safekeeping."},
    {"id": "n525e3q091", "exam": 4, "topic": "Human trafficking: minors", "type": "mcq", "bloom": "Comprehension", "stem": "The nurse learns that another young woman in the same household is 16 years old. Which statement about trafficking involving a minor is accurate?", "options": ["The same proof of coercion is required regardless of the person's age", "For a person under 18, no force, fraud or coercion needs to be proven", "A minor must disclose the situation before any report can be made", "Trafficking of a minor is reported to the Disabled Persons Protection Commission"], "correct": [1], "rationale": "Human trafficking is recruiting, harboring or transporting a person for forced labor or commercial sex by force, deception or coercion, but for anyone under 18 no coercion needs to be established. A child in this situation is reported to child protective services.", "whyNot": ["The requirement to show force, fraud or coercion applies to adults; it is not required for a minor.", "", "Reporting rests on reasonable suspicion; a disclosure is not required.", "That commission receives reports about disabled adults aged 18 to 59; a child is reported to child protective services."], "caseId": "c4traffic", "caseTitle": "Case 4 - A clinic visit with a companion", "scenario": "A 19-year-old woman is brought to a community clinic by a man who says he is her cousin. He stays beside her, answers questions directed to her, and says they cannot stay long. The woman avoids eye contact, appears underweight, and has bruising on both upper arms in various stages of healing. She has no identification and gives an address the man corrects. When the nurse asks about her living situation, the man says she lives with several other young women who work with him and that he holds their documents for safekeeping."},
    {"id": "n525e3q092", "exam": 4, "topic": "Youth violence prevention", "type": "sata", "bloom": "Application", "stem": "A nurse is planning primary prevention of youth violence in a community. Which strategies work best with this age group? Select all that apply.", "options": ["School-based conflict-resolution and social-emotional learning programs", "Anti-bullying programs", "Mentoring and safe after-school recreation programs", "Involving youth themselves in designing the programs", "Teaching families about safe firearm storage", "Lecture-based assemblies describing the penalties for violent crime"], "correct": [0, 1, 2, 3, 4], "rationale": "The goal is to stop violence before it begins, which is primary prevention: school-based conflict resolution and social-emotional programs, anti-bullying programs, mentoring and safe after-school recreation, parenting education, safe firearm storage, screening for depression, suicide and substance use, involving youth in program design, and addressing social determinants such as jobs and safe neighborhoods. Teens respond best to peer involvement, mentoring and skills-building rather than lectures.", "whyNot": ["", "", "", "", "", "Teens respond best to peer involvement, mentoring and skills-building rather than lectures."]},
    {"id": "n525e3q093", "exam": 4, "topic": "Community factors in violence", "type": "mcq", "bloom": "Analysis", "stem": "A nurse is assessing community-level factors that influence rates of violence in a neighborhood. Which finding would the nurse expect to be associated with lower rates of violence?", "options": ["High population density combined with very few available jobs in the neighborhood", "Widespread media coverage of violent events occurring in the community", "Well-maintained parks, pools and recreation programs with school and police support services", "An economic downturn that increases work-related stress among residents"], "correct": [2], "rationale": "Community resources such as parks, pools, recreation and school and police support services are associated with decreased violence. Risk-increasing community factors include crowding with a lack of jobs leading to despair and gangs, work stress spilling into the home especially during economic downturns, and media that can model violence.", "whyNot": ["Crowding and lack of jobs lead to despair and gang involvement and are associated with more violence.", "Media raises awareness but can also model violence, so coverage is not protective.", "", "Work stress and frustration spill into the home and worsen in economic downturns."]},
    {"id": "n525e3q094", "exam": 4, "topic": "Restraint safety", "type": "sata", "bloom": "Application", "stem": "A nurse must apply a wrist restraint to a client who is pulling at a central line after all alternatives have failed. Which actions are required? Select all that apply.", "options": ["Obtain a provider prescription that states the reason, type, location and time limit", "Secure the restraint to the bed frame with a quick-release knot", "Ensure two fingers fit under the restraint", "Use the restraint for the shortest time necessary", "Accept the family's written consent in place of a provider order", "Tie the restraint to the side rail so it moves with the rail"], "correct": [0, 1, 2, 3], "rationale": "Restraints are a last resort for the shortest time, used to protect the patient or others. There are no PRN orders, a provider face-to-face assessment is required, and the order must include the reason, location and type, length of time and justification. The restraint is tied to the bed frame rather than the side rail with a quick-release knot, and two fingers should fit underneath. Family consent does not replace an order.", "whyNot": ["", "", "", "", "Family consent does not replace a provider order; a prescription is required.", "Restraints are tied to the bed frame, not the side rail, because a moving rail can injure the client."]},
    {"id": "n525e3q095", "exam": 4, "topic": "Restraint orders", "type": "mcq", "bloom": "Application", "stem": "A provider writes an order reading \"soft wrist restraints PRN for agitation.\" How should the nurse respond to this order?", "options": ["Apply the restraints whenever the client becomes agitated as written", "Apply the restraints only if the family agrees at the time", "Use the order for up to 24 hours and then request renewal", "Clarify the order, because restraints may not be ordered on a PRN basis"], "correct": [3], "rationale": "There are no PRN orders for restraints. A valid order requires a provider face-to-face assessment and must state the reason, the location and type, the length of time and the justification. The nurse advocates for the client when concerned about restraint use.", "whyNot": ["Acting on a PRN restraint order violates the standard that such orders are not permitted.", "Family agreement does not substitute for a valid order, and the underlying order is still invalid.", "The order itself is not valid, and time limits apply to properly written orders rather than legitimizing a PRN order.", ""]},
    {"id": "n525e3q096", "exam": 4, "topic": "Fall prevention", "type": "sata", "bloom": "Application", "stem": "An 81-year-old client admitted with a urinary tract infection is confused and has attempted to climb out of bed twice. Which fall-prevention interventions should the nurse implement? Select all that apply.", "options": ["Move the client to a room close to the nurses' station", "Round on the client at least hourly", "Establish a scheduled toileting routine", "Keep the bed in the lowest position with the call light in reach", "Raise all four side rails to keep the client in bed", "Request a PRN sedative to be given when the client becomes restless"], "correct": [0, 1, 2, 3], "rationale": "Fall prevention includes a room close to the nurses' station, frequent rounding at least hourly, a toileting schedule, a low bed and the call light within reach. Four side rails up constitute a restraint and increase fall injury, and PRN restraints or sedatives are not appropriate. Risk factors here include the new environment and disorientation, infection causing delirium in an older adult, age, and urinary urgency from the infection.", "whyNot": ["", "", "", "", "Four raised side rails function as a restraint and increase the severity of injury if the client climbs over them.", "PRN sedatives for restlessness increase confusion and fall risk and are not an approved fall-prevention measure."]},
    {"id": "n525e3q097", "exam": 4, "topic": "Fall risk factors", "type": "sata", "bloom": "Analysis", "stem": "The nurse documents the fall risk factors for the 81-year-old client described above. Which factors apply to this client? Select all that apply.", "options": ["Being in an unfamiliar environment and becoming disoriented", "Infection leading to delirium in an older adult", "Advanced age", "Urinary urgency and frequency from the infection", "All clients with any infection are at high fall risk", "The client's cultural background determines fall risk"], "correct": [0, 1, 2, 3], "rationale": "Fall risks include a new environment and disorientation, infection such as a urinary tract infection leading to delirium in an older adult, age, urinary urgency and frequency, staffing and communication gaps, call-light issues, and cultural concerns about asking for help. It is not accurate to state that every client with an infection is at high risk.", "whyNot": ["", "", "", "", "This overgeneralizes; the relevant mechanism is infection causing delirium and urgency in an older adult.", "Cultural concerns can affect how care is delivered, but background itself is not a fall risk factor."]},
    {"id": "n525e3q098", "exam": 4, "topic": "Fire response: RACE", "type": "mcq", "bloom": "Application", "stem": "A nurse discovers a fire in a trash can in a client's room. Two ambulatory clients are in the room with the fire. Which action should the nurse take first?", "options": ["Move the two clients out of the room", "Pull the fire alarm in the hallway", "Close the door to contain the fire", "Obtain the extinguisher and aim it at the base of the flames"], "correct": [0], "rationale": "RACE orders the response: Rescue clients in immediate danger, Alarm by pulling the alarm and calling, Contain by closing doors and windows, then Extinguish or evacuate. The two ambulatory clients in the room are in immediate danger, so they are moved first.", "whyNot": ["", "Sounding the alarm is the second step; the clients in immediate danger are moved first.", "Containing comes after rescue and alarm in the sequence.", "Extinguishing is the last step, after people in immediate danger are moved, the alarm is sounded and the fire is contained."]},
    {"id": "n525e3q099", "exam": 4, "topic": "Fire extinguisher use", "type": "mcq", "bloom": "Application", "stem": "After the clients are moved and the alarm has sounded, the nurse prepares to use an extinguisher on a small paper fire in a trash can. Which sequence should the nurse follow?", "options": ["Aim at the top of the flames, pull the pin, squeeze and sweep", "Pull the pin, aim at the base of the fire, squeeze the handle and sweep side to side", "Squeeze the handle, pull the pin, aim at the base and sweep", "Pull the pin, aim at the flames, sweep and then squeeze the handle"], "correct": [1], "rationale": "The extinguisher sequence is PASS: Pull the pin, Aim at the base, Squeeze, Sweep. A trash fire involving paper is Class A; Class B covers flammable liquids and grease and Class C covers electrical fires.", "whyNot": ["The pin must be pulled before the extinguisher will discharge, and the stream is aimed at the base rather than the flames.", "", "Squeezing before pulling the pin will not discharge the extinguisher.", "Sweeping before squeezing releases nothing, and the stream must be directed at the base of the fire."]},
    {"id": "n525e3q100", "exam": 4, "topic": "Home safety for infants", "type": "sata", "bloom": "Application", "stem": "A nurse is teaching new parents about home safety for their infant. Which instructions should the nurse include? Select all that apply.", "options": ["Keep medications and chemicals out of reach", "Place safety gates at both the top and the bottom of stairs", "Set the water heater at or below 120 degrees Fahrenheit", "Keep pillows and other soft items out of the crib", "Use a wheeled walker to help the infant learn to walk", "Place a gate only at the top of the stairs to prevent falls"], "correct": [0, 1, 2, 3], "rationale": "Infant home safety includes keeping medications and chemicals out of reach, safety gates at the top and bottom of stairs, a water heater set at 120 degrees Fahrenheit or lower, no wheeled walkers, and no pillows or soft items in the crib.", "whyNot": ["", "", "", "", "Wheeled walkers are specifically to be avoided because of the injury risk they create.", "Gates belong at both the top and the bottom of the stairs."]},
    {"id": "n525e3q101", "exam": 5, "topic": "History of school nursing", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse is presenting on the origins of school nursing in the United States. Which statement about its history is accurate?", "options": ["School nursing began with the passage of federal disability education law in 1975", "The first school nurses focused primarily on mental health services", "Lina Rogers became the first United States school nurse in New York City in 1902", "National standards for school nursing were first published in 1902"], "correct": [2], "rationale": "Lina Rogers was the first United States school nurse, in New York City in 1902, and early practice focused on infection control and vision and hearing checks. The Education for All Handicapped Children Act, later IDEA, opened public schools to students with disabilities in 1975, bringing individualized education programs and health plans and procedures such as tube feedings, seizure care and tracheostomy suctioning. The first standards came in 1983.", "whyNot": ["That law opened public schools to students with disabilities and expanded the nurse's role, but school nursing began decades earlier.", "The early focus was infection control and vision and hearing checks; mental health became prominent much later.", "", "The first standards from the professional associations appeared in 1983, not at the founding of the specialty."]},
    {"id": "n525e3q102", "exam": 5, "topic": "School medication administration", "type": "sata", "bloom": "Application", "stem": "A parent brings a medication to school for the nurse to give to a student during the school day. Which requirements must be met before the nurse administers it? Select all that apply.", "options": ["The medication is in its original labeled container", "There is a provider order for the medication", "Signed parental consent is on file", "A drug reference is available to the nurse", "The student carries the medication and self-administers it in class", "A teacher confirms verbally that the parent approves the medication"], "correct": [0, 1, 2, 3], "rationale": "Medication administration in school requires the prescribed medication in its original labeled container, a provider order, signed parental consent and a drug reference. Students do not carry over-the-counter or prescribed medications per this policy, although state law and individual plans create exceptions for inhalers and epinephrine. Over-the-counter medication may be given with a parent request plus a standing order.", "whyNot": ["", "", "", "", "Per the school policy described, students do not carry over-the-counter or prescribed medications themselves.", "Verbal confirmation from staff does not substitute for signed parental consent and a provider order."]},
    {"id": "n525e3q103", "exam": 5, "topic": "Anaphylaxis in school", "type": "mcq", "bloom": "Application", "stem": "A student with a known peanut allergy develops hives, lip swelling and audible wheezing minutes after lunch. Which action should the school nurse take first?", "options": ["Call 911 and wait for emergency services to arrive", "Give an oral antihistamine and observe the student closely", "Contact the parents to confirm the student's allergy history", "Give intramuscular epinephrine in the lateral thigh"], "correct": [3], "rationale": "For anaphylaxis the school nurse gives intramuscular epinephrine in the lateral thigh first and then calls 911, following the student's emergency action plan. Schools maintain epinephrine policies and staff training, along with allergen-safe lunch practices.", "whyNot": ["Emergency services are called, but epinephrine is given first because the reaction progresses in minutes.", "An antihistamine does not reverse airway swelling or bronchospasm and delays the only treatment that does.", "The allergy is already known and the reaction is in progress; calling first delays life-saving treatment.", ""]},
    {"id": "n525e3q104", "exam": 5, "topic": "Head lice management", "type": "sata", "bloom": "Application", "stem": "A school nurse identifies head lice in a second-grade student and teaches the family about treatment. Which instructions should the nurse include? Select all that apply.", "options": ["Use a pediculicide shampoo followed by combing with a fine-tooth comb", "Repeat the treatment in seven to ten days", "Wash linens and clothing used in the last two days in hot water", "Do not share hats, combs or scarves", "Treat the home with an insecticide spray because lice can jump between rooms", "Keep the child home from school until all nits have been removed"], "correct": [0, 1, 2, 3], "rationale": "Head lice spread by direct contact because they crawl only and cannot hop, jump or fly. Treatment is a pediculicide shampoo plus a fine-tooth comb, repeated in seven to ten days; linens and clothing used in the last two days are washed in hot water; hats, combs and scarves are not shared; and hair is checked weekly. A nit hatches in six to seven days and becomes an adult in about ten days, which is why the repeat treatment is timed as it is.", "whyNot": ["", "", "", "", "Lice crawl only; they cannot hop, jump or fly, so spraying the home is unnecessary.", "Exclusion until every nit is gone is not part of the described management, which centers on treatment, combing and preventing sharing."]},
    {"id": "n525e3q105", "exam": 5, "topic": "Levels of prevention in schools", "type": "mcq", "bloom": "Analysis", "stem": "A school nurse performs vision and hearing screening, teaches a healthy-eating unit to fifth graders, and manages the daily care of a student with a tracheostomy. How should the nurse classify these three activities in order?", "options": ["Secondary, primary, tertiary", "Primary, secondary, tertiary", "Secondary, tertiary, primary", "Tertiary, primary, secondary"], "correct": [0], "rationale": "In schools, primary prevention includes teaching healthy lifestyles, school-entry immunizations, injury prevention and substance-abuse and disease-prevention education. Secondary prevention includes vision, hearing, body mass index and scoliosis screening, caring for ill or injured students, giving medication, identifying child abuse and suicide-risk screening. Tertiary prevention includes caring for children with chronic health problems such as asthma, diabetes and autism, and homebound children.", "whyNot": ["", "Screening is early detection and therefore secondary, while the healthy-eating unit prevents problems before they occur and is primary, so the first two are reversed.", "Teaching healthy eating is primary prevention and caring for a student with a chronic condition is tertiary, so the last two are reversed.", "Vision and hearing screening is early detection, which is secondary prevention, not tertiary."]},
    {"id": "n525e3q106", "exam": 5, "topic": "FERPA, HIPAA and confidentiality", "type": "mcq", "bloom": "Analysis", "stem": "A parent of a 15-year-old student asks the school nurse to see everything in the student's health file, including notes about a recent visit for a sexually transmitted infection. Which action by the nurse is correct?", "options": ["Provide the parent with the entire file, because parents may view a minor's record until age 18", "Share the education record but keep the protected information covered by the mature minor concept separate", "Refuse all access, because the school nurse's records are protected under HIPAA", "Refer the parent to the student's primary care provider to obtain the whole record"], "correct": [1], "rationale": "In schools receiving federal funds the school nurse's health records are education records under FERPA, and parents have access until the student turns 18, while HIPAA governs health care providers and insurers. However, protected information under the mature minor concept, such as sexually transmitted infection treatment, pregnancy and birth control, is kept separate and not shared with parents.", "whyNot": ["Parents may access education records, but information protected under the mature minor concept is kept separate and is not shared.", "", "In schools receiving federal funds the nurse's health records are education records under FERPA, and HIPAA governs health care providers and insurers.", "This avoids the question; the nurse must know which parts of the school record are releasable and which are protected."]},
    {"id": "n525e3q107", "exam": 5, "topic": "Breaching confidentiality in schools", "type": "mcq", "bloom": "Application", "stem": "A high school student tells the school nurse in confidence that she has been thinking about killing herself and has access to a firearm at home. Which action should the nurse take?", "options": ["Keep the disclosure confidential because it was given in confidence", "Wait to see whether the student repeats the statement at a later visit", "Break confidentiality and notify parents and school administration", "Document the conversation and schedule a follow-up visit next week"], "correct": [2], "rationale": "Confidentiality is breached when a student discloses suspected child abuse or threats of harm to self or others; the nurse reports to parents and the school and possibly to child protective services, and the school nurse is always a mandated reporter. Access to a firearm raises lethality and makes immediate action essential.", "whyNot": ["Confidentiality is broken when a student discloses threats of harm to self or others, precisely so the student can be protected.", "Waiting leaves a student with ideation and access to lethal means unprotected.", "", "Documentation alone does not address immediate danger, and a week's delay is unsafe."]},
    {"id": "n525e3q108", "exam": 5, "topic": "IEP, 504 plan and IHP", "type": "mcq", "bloom": "Analysis", "stem": "A student with type 1 diabetes has no learning disability but needs to check glucose and eat snacks during class. Which plan provides the accommodations this student needs to access regular education?", "options": ["An individualized education program", "An emergency action plan", "A diabetes medical management plan", "A 504 plan"], "correct": [3], "rationale": "A 504 plan, under Section 504 of the Rehabilitation Act, provides accommodations so a student with a disability or health condition such as diabetes or a food allergy can access regular education. An individualized education program under IDEA provides special-education services for a qualifying disability, the individualized health care plan is the nurse's nursing-process plan, and the emergency action plan covers acute events.", "whyNot": ["This provides special-education services under IDEA for a qualifying disability affecting learning, which this student does not have.", "An emergency action plan directs what to do in an acute event such as severe hypoglycemia, not the routine daily accommodations.", "This is the provider's medical orders for the student's diabetes care, not the school document granting classroom accommodations.", ""]},
    {"id": "n525e3q109", "exam": 5, "topic": "Chronic conditions in schools", "type": "mcq", "bloom": "Comprehension", "stem": "A school nurse is planning staff training on the chronic condition most commonly encountered among school-aged children. Which condition should the training address first?", "options": ["Asthma", "Type 1 diabetes", "Scoliosis", "Seizure disorder"], "correct": [0], "rationale": "Asthma is the leading chronic illness in schools. Management includes an individual asthma action plan with green, yellow and red zones, accessible quick-relief inhalers subject to self-carry rules, and reduction of triggers such as dust, mold and smoke.", "whyNot": ["", "Diabetes requires a medical management plan and trained staff, but asthma is identified as the leading chronic illness in schools.", "Scoliosis is detected through routine school screening rather than being the leading chronic illness managed daily.", "Seizure care is part of the expanded school nurse role, but it is not the most common chronic illness in this population."]},
    {"id": "n525e3q110", "exam": 5, "topic": "School nurse as consultant: data", "type": "sata", "bloom": "Analysis", "stem": "Before planning any changes, what additional information does the chief school nurse most need? Select all that apply.", "options": ["The ages and grade levels of the children expected to enroll", "The current nurse-to-student ratio and how nurses are distributed across the schools", "The budget available for proposed additions and changes", "The number of families expected to move into the community", "The amount of involvement expected from the manufacturing company", "The cultural diversity of the expected population increase"], "correct": [0, 1, 2], "rationale": "To update the service plan effectively the chief school nurse needs the ages and grades of the incoming children, the current nurse-to-student ratio and distribution, and the budget for changes. These three determine how many nurse hours and what kinds of services the expanded enrollment will require.", "whyNot": ["", "", "", "Household counts are less directly useful than the number, ages and grades of the students who will actually need services.", "The company may be a reasonable partner, but its involvement is not information needed initially to size and plan the services.", "This matters for how services are delivered later, but it is not what the nurse needs first to determine staffing and service capacity."], "caseId": "c5wayne", "caseTitle": "Case 5 - Wayne County school health services", "scenario": "An international manufacturing company has announced plans to locate a large plant in Wayne County. The county school board has asked the chief school nurse to report on the health services currently offered in the public schools and what changes are advisable to meet an anticipated increase in enrollment. Wayne County is a small rural county with 10 schools serving kindergarten through high school and a total enrollment of 4,209 students. An additional 200 to 350 students are expected to enroll for the fall term in 16 months. All 10 schools are currently served by two full-time and two part-time nurses."},
    {"id": "n525e3q111", "exam": 5, "topic": "School nurse as consultant: stakeholders", "type": "sata", "bloom": "Application", "stem": "Acting in the role of consultant, from which stakeholder groups should the chief school nurse initially seek input? Select all that apply.", "options": ["Parents", "Teachers and school administration", "The school board", "The school nurses themselves", "The student population and the medical community", "No outside groups, so the plan reflects nursing judgment alone"], "correct": [0, 1, 2, 3, 4], "rationale": "In the consultant role the chief school nurse gathers input from all stakeholder groups: parents, teachers, the school board, the school nurses, students, the medical community and school administration. The manufacturing company is also a reasonable partner in this situation.", "whyNot": ["", "", "", "", "", "A consultant gathers input from all stakeholder groups; excluding them would produce a plan without the support needed to implement it."], "caseId": "c5wayne", "caseTitle": "Case 5 - Wayne County school health services", "scenario": "An international manufacturing company has announced plans to locate a large plant in Wayne County. The county school board has asked the chief school nurse to report on the health services currently offered in the public schools and what changes are advisable to meet an anticipated increase in enrollment. Wayne County is a small rural county with 10 schools serving kindergarten through high school and a total enrollment of 4,209 students. An additional 200 to 350 students are expected to enroll for the fall term in 16 months. All 10 schools are currently served by two full-time and two part-time nurses."},
    {"id": "n525e3q112", "exam": 5, "topic": "School nurse as consultant: scope", "type": "sata", "bloom": "Analysis", "stem": "Which focus areas belong in the updated school health service plan? Select all that apply.", "options": ["Consulting", "Counseling", "Health education", "Direct caregiving", "Case management and community outreach", "Student discipline and academic integrity"], "correct": [0, 1, 2, 3, 4], "rationale": "The areas of school nursing practice included in the service plan are consulting, counseling, health education, direct caregiving, case management and community outreach. Discipline and academic integrity are school administrative functions, not nursing roles.", "whyNot": ["", "", "", "", "", "Discipline and academic integrity are not school nursing roles and do not belong in a school health service plan."], "caseId": "c5wayne", "caseTitle": "Case 5 - Wayne County school health services", "scenario": "An international manufacturing company has announced plans to locate a large plant in Wayne County. The county school board has asked the chief school nurse to report on the health services currently offered in the public schools and what changes are advisable to meet an anticipated increase in enrollment. Wayne County is a small rural county with 10 schools serving kindergarten through high school and a total enrollment of 4,209 students. An additional 200 to 350 students are expected to enroll for the fall term in 16 months. All 10 schools are currently served by two full-time and two part-time nurses."},
    {"id": "n525e3q113", "exam": 5, "topic": "School nurse as consultant: staffing", "type": "mcq", "bloom": "Analysis", "stem": "The chief school nurse reviews the finding that 10 schools and 4,209 students are currently served by two full-time and two part-time nurses, with 200 to 350 more students expected. Which recommendation follows from this finding?", "options": ["Maintain current staffing and delegate more tasks to unlicensed school staff", "Hire an additional full-time nurse and significantly increase part-time hours", "Reduce health services at the smaller schools to concentrate nurses at the larger ones", "Wait until the new students have enrolled before changing staffing"], "correct": [1], "rationale": "Four nurses, two of them part-time, covering 10 schools and more than 4,200 students is the central staffing finding, and the enrollment increase makes it more acute. The recommendation is to increase the nurse-to-student ratio by hiring an additional full-time nurse and significantly increasing the hours of the part-time nurses, along with additional supplies and regular training for delegated staff.", "whyNot": ["Delegation requires training and nurse oversight, which this staffing level cannot provide, and delegation does not replace needed nurse hours.", "", "Cutting services at some schools leaves those students without coverage rather than meeting the increased need.", "The report was requested specifically to plan ahead, and hiring after the influx leaves students unserved during the transition."], "caseId": "c5wayne", "caseTitle": "Case 5 - Wayne County school health services", "scenario": "An international manufacturing company has announced plans to locate a large plant in Wayne County. The county school board has asked the chief school nurse to report on the health services currently offered in the public schools and what changes are advisable to meet an anticipated increase in enrollment. Wayne County is a small rural county with 10 schools serving kindergarten through high school and a total enrollment of 4,209 students. An additional 200 to 350 students are expected to enroll for the fall term in 16 months. All 10 schools are currently served by two full-time and two part-time nurses."},
    {"id": "n525e3q114", "exam": 5, "topic": "Evaluating school health programs", "type": "sata", "bloom": "Application", "stem": "A year after the changes are implemented, the chief school nurse evaluates their effectiveness. Which outcome measures should be compared before and after? Select all that apply.", "options": ["Student absenteeism rates", "Immunization compliance rates", "Emergency department visits and 911 calls originating from the schools", "Students returned to class compared with those sent home", "Completion of referrals generated by screening", "The number of hours the nurses spend in the health office"], "correct": [0, 1, 2, 3, 4], "rationale": "School health programs are evaluated by comparing outcomes before and after: absenteeism, immunization compliance, emergency department visits and 911 calls, asthma and diabetes control, body mass index trends, students returned to class versus sent home, and completion of screening referrals.", "whyNot": ["", "", "", "", "", "Time spent in an office measures activity rather than whether student health outcomes improved."], "caseId": "c5wayne", "caseTitle": "Case 5 - Wayne County school health services", "scenario": "An international manufacturing company has announced plans to locate a large plant in Wayne County. The county school board has asked the chief school nurse to report on the health services currently offered in the public schools and what changes are advisable to meet an anticipated increase in enrollment. Wayne County is a small rural county with 10 schools serving kindergarten through high school and a total enrollment of 4,209 students. An additional 200 to 350 students are expected to enroll for the fall term in 16 months. All 10 schools are currently served by two full-time and two part-time nurses."},
    {"id": "n525e3q115", "exam": 5, "topic": "OSHA and NIOSH", "type": "mcq", "bloom": "Comprehension", "stem": "An occupational health nurse is explaining the difference between two federal bodies created around the same period. Which statement accurately distinguishes them?", "options": ["NIOSH enforces the standards, while OSHA conducts research into workplace hazards", "Both agencies enforce workplace safety standards within their own assigned industries", "OSHA develops and enforces safety standards, while NIOSH conducts research and makes recommendations", "OSHA is part of the CDC, and NIOSH is part of the federal Department of Labor"], "correct": [2], "rationale": "OSHA, created by the Occupational Safety and Health Act of 1970 and part of the Department of Labor, develops and enforces safety standards through inspections and fines and provides training, outreach and education. NIOSH is a research agency within the CDC that conducts studies and makes safety recommendations, providing the evidence base for OSHA standards but not enforcing them.", "whyNot": ["This reverses the two roles; NIOSH explicitly does not enforce.", "Only OSHA enforces; NIOSH provides the evidence base through research.", "", "The affiliations are reversed: OSHA is in the Department of Labor and NIOSH is part of the CDC."]},
    {"id": "n525e3q116", "exam": 5, "topic": "Workplace hazard categories", "type": "mcq", "bloom": "Analysis", "stem": "An occupational health nurse assesses a warehouse where workers repeatedly lift heavy boxes from floor level while twisting to place them on a conveyor. Which hazard category does this describe?", "options": ["Physical", "Psychosocial", "Chemical", "Ergonomic"], "correct": [3], "rationale": "Ergonomic hazards are heavy lifting, repetitive motion, vibration and awkward posture, which is exactly what repeated lifting from floor level with twisting involves. The other categories are chemical, physical, biological and psychosocial.", "whyNot": ["Physical hazards include noise, radiation, temperature extremes, vibration, lighting, lasers, unsafe machinery and transportation accidents rather than body mechanics during a task.", "Psychosocial hazards involve interpersonal relationships, shift work, stress and workplace violence.", "Chemical hazards include solvents, adhesives, toxic dusts, paints, cleaning solutions and diesel exhaust.", ""]},
    {"id": "n525e3q117", "exam": 5, "topic": "Epidemiologic triad at work", "type": "mcq", "bloom": "Analysis", "stem": "An occupational health nurse reviews injury data and must decide where to concentrate a new safety initiative. Which group of workers should the nurse target as being at highest risk?", "options": ["Workers with less than one year of experience", "Workers who have been with the company longest", "Workers who have already filed a workers' compensation claim", "Workers who rotate shifts in a clockwise direction"], "correct": [0], "rationale": "In the epidemiologic triad applied to work, the host is the worker and the worker's family, with characteristics including age, gender, health status, work practices, ethnicity and lifestyle, and workers with less than one year of experience are at highest risk. The agent is the hazard, with sprains and strains the most frequent disabling conditions, and rotating shifts clockwise is beneficial.", "whyNot": ["", "Experience is protective in this data; the highest risk sits with workers new to the job.", "A prior claim identifies someone already injured; it is not the characteristic that marks highest risk going forward.", "Rotating shifts clockwise, from day to evening to night, is described as beneficial rather than a risk."]},
    {"id": "n525e3q118", "exam": 5, "topic": "Hazard Communication Standard", "type": "mcq", "bloom": "Application", "stem": "A worker asks the occupational health nurse how to find out what chemicals are used in his department and what they can do to him. Which response reflects the employer's obligation under the Hazard Communication Standard?", "options": ["\"That information is proprietary and is available only to supervisors and managers.\"", "\"Your employer must inventory and label these chemicals and keep safety data sheets accessible to you.\"", "\"You can request that information only by filing a formal written complaint with OSHA.\"", "\"Only those chemicals classified as carcinogens must be documented and labeled.\""], "correct": [1], "rationale": "The Hazard Communication Standard is the Right-to-Know standard: employers must inventory toxic agents, label them, keep information sheets, formerly called material safety data sheets and now safety data sheets, and educate employees. Records of all chemicals are kept in a binder accessible to all employees.", "whyNot": ["The standard is called Right-to-Know precisely because employees must have access to this information.", "", "A complaint is not required; the employer must make the information available in the workplace.", "The requirement covers the inventory of toxic agents in use, not only a single class of them."]},
    {"id": "n525e3q119", "exam": 5, "topic": "Hierarchy of controls", "type": "mcq", "bloom": "Analysis", "stem": "An occupational health nurse is addressing needlestick injuries on a hospital unit. The unit currently relies on staff training and reminders to use caution. Which recommendation would be most effective?", "options": ["Increase the frequency of the existing safety training sessions", "Require staff to wear a second pair of gloves during procedures", "Convert the unit to safety-engineered needle devices", "Post reminder signage at every sharps container on the unit"], "correct": [2], "rationale": "The hierarchy of controls ranks interventions from most to least effective: elimination, substitution, engineering controls such as ventilation, safety needles and lift equipment, administrative controls such as training, shift rotation and policies, and finally personal protective equipment, which is the last line of defense. Safety-engineered needles are an engineering control and outrank the training already being used.", "whyNot": ["Training is an administrative control, which sits below engineering controls in effectiveness and is already in place.", "Personal protective equipment is the last line of defense and does not prevent a needle from penetrating.", "", "Signage is another administrative measure and does not change the device that causes the injury."]},
    {"id": "n525e3q120", "exam": 5, "topic": "Health surveillance as secondary prevention", "type": "mcq", "bloom": "Application", "stem": "An occupational health nurse performs periodic hearing tests on workers exposed to high noise levels and tracks results over time. Which level of prevention does this activity represent?", "options": ["Primary prevention", "Tertiary prevention", "This is a regulatory function rather than a level of prevention", "Secondary prevention"], "correct": [3], "rationale": "Health surveillance and periodic screening are secondary prevention: they find illness early and allow the hazard to be modified. Worker assessment includes a history and physical emphasizing exposures and an occupational health history, while workplace assessment is done through a worksite walk-through.", "whyNot": ["Primary prevention would be reducing the noise at its source or providing hearing protection before any loss occurs.", "Tertiary prevention would involve managing and rehabilitating a worker whose hearing loss is already established.", "Surveillance is a nursing prevention activity, and it is also used to evaluate whether controls are working.", ""]},
    {"id": "n525e3q121", "exam": 5, "topic": "Total Worker Health", "type": "mcq", "bloom": "Comprehension", "stem": "An occupational health nurse describes an approach in which policies address wages, workload, benefits and paid leave alongside traditional safety programs. Which concept does this describe?", "options": ["Total Worker Health", "The Hazard Communication Standard", "Workers' compensation", "The epidemiologic triad"], "correct": [0], "rationale": "Total Worker Health describes policies that integrate safety and wellness and address wages, workload, benefits and paid leave, recognizing that the workplace is a social determinant of health. Managing Total Worker Health is one of the four core competency categories for occupational health nurses.", "whyNot": ["", "That standard concerns inventorying, labeling and communicating chemical hazards to employees.", "Workers' compensation is no-fault insurance that pays medical costs and lost wages after a work-related injury or illness.", "The triad is an analytic framework of host, agent and environment used to understand workplace risk."]},
    {"id": "n525e3q122", "exam": 5, "topic": "Workers' compensation and case management", "type": "mcq", "bloom": "Application", "stem": "A worker sustains a back injury while lifting at work. The occupational health nurse documents the injury, coordinates the worker's care and plans a modified-duty return to work. Which nursing role is the nurse performing?", "options": ["Researcher", "Case manager", "Administrator", "Industrial hygienist"], "correct": [1], "rationale": "The occupational health nurse's case manager role coordinates care and return to work. Workers' compensation is state-run no-fault insurance paying medical costs and lost wages for work-related injury or illness, in exchange for which the employee generally cannot sue the employer. Other roles are clinician, counselor and consultant, educator, administrator and researcher, and the core team also includes an occupational physician, an industrial hygienist and a safety professional.", "whyNot": ["The researcher role generates and applies evidence about workplace health rather than coordinating one worker's care.", "", "The administrator role manages programs, compliance and records rather than coordinating an individual case.", "The industrial hygienist is a separate member of the core occupational health team who evaluates workplace exposures."]},
    {"id": "n525e3q123", "exam": 5, "topic": "Hazards for nurses", "type": "sata", "bloom": "Comprehension", "stem": "An occupational health nurse is presenting on hazards faced by nurses in their own workplace. Which hazards should be included? Select all that apply.", "options": ["Needlesticks and splash exposures", "Musculoskeletal pain from overexertion", "Respirable infectious diseases", "Violence from patients, families or staff", "Stress and overwork", "Hearing loss from prolonged exposure to industrial machinery"], "correct": [0, 1, 2, 3, 4], "rationale": "Hazards for nurses include needlesticks and splashes, musculoskeletal pain from overexertion addressed through ergonomics such as lateral-tilt beds, proper bed height and lift equipment, respirable infectious diseases, work-related illness, stress and overwork, chemicals, radiation, violence from patients, families or staff, falls and equipment misuse.", "whyNot": ["", "", "", "", "", "Noise-induced hearing loss is an industrial hazard; the hazards listed for nurses center on exposures, ergonomics, infection, stress and violence."]},
    {"id": "n525e3q124", "exam": 5, "topic": "Faith community nursing role", "type": "mcq", "bloom": "Application", "stem": "A faith community nurse is planning services for a congregation. Which set of activities best fits this nursing role?", "options": ["Complex wound care, intravenous therapy and medication administration in members' homes", "Leading worship services and providing formal religious instruction to members", "Health education and counseling, screenings, advocacy, referral and care coordination", "Diagnosing and treating acute illness among members of the congregation"], "correct": [2], "rationale": "The faith community nurse is a licensed registered nurse who promotes health as wholeness within a faith community using a holistic approach to physical, emotional, spiritual and social needs. Interventions include health education, health counseling, prayer, presencing, active listening, advocacy, referral and coordinating volunteers and programs, with a focus on health promotion, education, screenings such as blood pressure clinics, advocacy and care coordination rather than invasive procedures.", "whyNot": ["Faith community nurses focus on health promotion, education, screening, advocacy and care coordination rather than invasive hands-on procedures.", "These are clergy functions; the faith community nurse collaborates with clergy but does not take on their role.", "", "Diagnosis and treatment of acute illness falls outside the described scope of this role."]},
    {"id": "n525e3q125", "exam": 5, "topic": "Spirituality versus religiosity", "type": "mcq", "bloom": "Analysis", "stem": "A client tells the nurse, \"I don't belong to any church and I don't follow any religion, but I believe there is something greater than myself and that my life has meaning.\" How should the nurse interpret this statement?", "options": ["The client is expressing religiosity without spirituality", "The client has no spiritual needs that require nursing assessment", "The client is describing holistic care as it applies to her own life", "The client is expressing spirituality without religiosity"], "correct": [3], "rationale": "Spirituality is the sense or belief that there is something greater than oneself and more to being human than sensory experience; it is broader than religion, all people are spiritual, and it is not chosen. Religiosity is the quality of a person's religious beliefs and experiences and the role religion plays in society, where religion is an organized, shared system of beliefs, practices, worship and rituals involving choice. A person can be spiritual but not religious, or the reverse.", "whyNot": ["Religiosity involves organized, shared beliefs and practices, which the client explicitly does not hold.", "All people are described as spiritual, and this client has articulated meaning and connectedness that warrant assessment.", "Holistic care is an approach taken by the nurse to the whole person, not a description of the client's beliefs.", ""]},
    {"id": "n525e3q126", "exam": 5, "topic": "Spiritual versus religious care", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse provides one-to-one, person-centered support that makes no assumptions about the client's convictions or life orientation. Which type of care is the nurse providing?", "options": ["Spiritual care", "Religious care", "Holistic care", "Pastoral counseling"], "correct": [0], "rationale": "Spiritual care is usually one-to-one, entirely person-centered, and makes no assumptions about personal conviction or life orientation. Religious care is given in the context of a faith community's shared beliefs, values, liturgies and lifestyles.", "whyNot": ["", "Religious care is given within the context of a faith community's shared beliefs, values, liturgies and lifestyles.", "Holistic care looks at the whole person including physical, emotional, social and spiritual well-being, which is broader than what is described here.", "This is a clergy function rather than the person-centered spiritual care described in this material."]},
    {"id": "n525e3q127", "exam": 5, "topic": "History of faith community nursing", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse is describing how parish nursing developed into the specialty known today. Which statement is accurate?", "options": ["The American Nurses Association first recognized parish nursing as a specialty in 1984", "Granger Westberg introduced parish nurses to Chicago-area churches in 1984, and it was renamed in 2005", "The specialty was renamed faith community nursing in 1997 to reflect its Christian roots", "Lillian Wald founded the first parish nursing program at the Henry Street Settlement in 1893"], "correct": [1], "rationale": "Reverend Granger Westberg, a Lutheran chaplain, created wholistic health centers in congregations in 1979 and introduced parish nurses to Chicago-area churches in 1984. The Parish Nurse Resource Center followed in 1986, becoming the International Parish Nurse Resource Center and now the Westberg Institute. The American Nurses Association recognized parish nursing as a specialty in 1997, and it was renamed faith community nursing in 2005 to include all faith traditions.", "whyNot": ["Recognition as a specialty came in 1997; 1984 is when Westberg introduced parish nurses to Chicago-area churches.", "", "The 2005 renaming was specifically to include all faith traditions, not to emphasize one.", "Lillian Wald founded the Henry Street Settlement in 1893 and influenced the field, but Westberg founded parish nursing."]},
    {"id": "n525e3q128", "exam": 5, "topic": "Spiritual assessment tools", "type": "mcq", "bloom": "Application", "stem": "A faith community nurse wants to assess a member's faith, its importance and influence, their community of support, and how to address these in care. Which assessment tool is the nurse using?", "options": ["HOPE", "START", "FICA", "AVPU"], "correct": [2], "rationale": "FICA assesses Faith and meaning, Importance and influence, Community, and how to Address spirituality in care. HOPE explores sources of Hope, Organized religion, Personal spirituality and practices, and Effects on care and end-of-life decisions. Either is paired with a congregational needs assessment covering demographics, health concerns and resources.", "whyNot": ["The HOPE tool explores sources of hope, organized religion, personal spirituality and practices, and effects on care and end-of-life decisions.", "START is a mass-casualty triage method, not a spiritual assessment tool.", "", "AVPU is a scale for level of responsiveness used in triage and neurologic assessment."]},
    {"id": "n525e3q129", "exam": 5, "topic": "Ethics and diversity in faith community nursing", "type": "mcq", "bloom": "Application", "stem": "A faith community nurse is caring for a congregation member whose religious beliefs about end-of-life care differ sharply from the nurse's own. Which action is most appropriate?", "options": ["Share the nurse's own beliefs so the member can consider another perspective", "Transfer the member's care to another nurse without further discussion", "Focus only on physical needs and avoid the spiritual dimension entirely", "Respect the member's beliefs and collaborate with clergy and community agencies in the plan"], "correct": [3], "rationale": "Faith community nursing requires respecting each person's beliefs without imposing one's own, collaborating with clergy, congregation leaders and community agencies, advocating for underserved members, and applying ethical principles with respect for cultural and religious diversity.", "whyNot": ["Imposing the nurse's beliefs violates the principle of respecting each person's convictions.", "Difference in belief does not by itself require transfer; respecting diversity is part of the role.", "Avoiding the spiritual dimension abandons the holistic approach that defines this specialty.", ""]},
    {"id": "n525e3q130", "exam": 5, "topic": "Faith communities as a health promotion setting", "type": "mcq", "bloom": "Analysis", "stem": "A public health department wants to expand health promotion into settings where residents already gather and trust the leadership. Which rationale best supports partnering with faith communities?", "options": ["Faith communities are trusted, influential and long-standing, making them an ideal setting for health promotion", "Faith communities can deliver clinical services at a lower cost than any other community setting", "Faith communities can require their members to participate in health programs", "Faith communities serve only those populations that have no other access to care"], "correct": [0], "rationale": "Healthy People 2030 identifies faith communities as an ideal setting for health promotion because they are trusted, influential and long-standing, with strong partnerships available with health institutions and agencies. The faith community care model provides lower-cost, holistic, community-based, patient-centered care for vulnerable and underserved populations through community partnerships.", "whyNot": ["", "Lower-cost holistic community care is part of the model, but the reason these settings are ideal is trust, influence and longevity.", "Participation is voluntary, and compelling it would conflict with the respect for autonomy central to the role.", "Congregations include members across the full range of access; the partnership is not limited to those without other options."]},
    {"id": "n525e3q131", "exam": 6, "topic": "Defining bioterrorism", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse is teaching a preparedness class and is asked how bioterrorism differs from terrorism generally. Which statement is accurate?", "options": ["Bioterrorism refers to any outbreak of an infectious disease that has a high death rate", "Bioterrorism is the intentional use of microorganisms or toxins to cause illness or death in people or livestock", "Bioterrorism refers only to attacks that use chemical agents such as ricin, sarin or mustard gas", "Bioterrorism describes the accidental release of a biological agent from a research laboratory"], "correct": [1], "rationale": "Terrorism is the intent to cause harm to an individual or population, and bioterrorism is the intentional use of microorganisms or toxins to cause illness or death in people, livestock or crops. Threats to prepare for include anthrax, plague, smallpox, botulism, viral hemorrhagic fevers, tularemia, chemical agents such as ricin, sarin and mustard gas, radiation and nuclear events, and electromagnetic pulse.", "whyNot": ["A naturally occurring outbreak is not bioterrorism; the defining feature is intentional release.", "", "Chemical agents are a separate threat category; bioterrorism involves microorganisms and toxins.", "An accidental release lacks the intent that defines terrorism."]},
    {"id": "n525e3q132", "exam": 6, "topic": "CDC agent categories", "type": "mcq", "bloom": "Analysis", "stem": "A nurse is reviewing the category system used to prioritize biological threat agents. Which description correctly characterizes a Category A agent?", "options": ["Moderately easy to disseminate, with high morbidity but a lower mortality rate", "An emerging pathogen that could be engineered for mass spread at some point in the future", "Easily disseminated or transmitted, with high morbidity and mortality and major public health impact", "An agent that causes illness only in livestock and crops rather than in people"], "correct": [2], "rationale": "Category A agents are the highest priority: easily disseminated or transmitted, with high morbidity and mortality, major public health impact and panic, and requiring special preparedness. They include anthrax, smallpox, botulism, plague, tularemia and the viral hemorrhagic fevers such as Ebola and Marburg.", "whyNot": ["This describes Category B agents such as brucellosis, Q fever, typhus and ricin toxin.", "This describes Category C agents such as influenza, multidrug-resistant tuberculosis and Hantavirus.", "", "Category A agents cause severe human disease; the categories are not defined by which species is affected."]},
    {"id": "n525e3q133", "exam": 6, "topic": "Category B and C agents", "type": "sata", "bloom": "Comprehension", "stem": "A nurse is classifying biological agents by category. Which agents belong in Category B? Select all that apply.", "options": ["Brucellosis", "Q fever", "Ricin toxin", "Food threats such as E. coli O157:H7, Salmonella and Shigella", "Smallpox", "Hantavirus"], "correct": [0, 1, 2, 3], "rationale": "Category B agents are moderately easy to disseminate with high morbidity but lower mortality, and need enhanced laboratory capacity and surveillance: brucellosis, Q fever, typhus, ricin toxin, food threats such as E. coli O157:H7, Salmonella and Shigella, water threats such as cholera, and Eastern equine encephalitis and West Nile. Category C covers emerging pathogens including influenza, multidrug-resistant tuberculosis, Hantavirus, tick-borne encephalitis and yellow fever.", "whyNot": ["", "", "", "", "Smallpox is a Category A agent because it is transmitted person to person with high morbidity and mortality.", "Hantavirus is a Category C agent, an emerging pathogen that could be engineered for mass spread."]},
    {"id": "n525e3q134", "exam": 6, "topic": "Inhalational anthrax", "type": "mcq", "bloom": "Analysis", "stem": "A postal worker presents with fever, chest discomfort, dyspnea and myalgia three days after a suspected anthrax exposure at a mail facility. Which action should the nurse take first?", "options": ["Place the client in airborne isolation before any treatment", "Wait for laboratory confirmation before starting antibiotics", "Obtain a detailed exposure history from the client's supervisor", "Initiate the prescribed intravenous antibiotics"], "correct": [3], "rationale": "Intravenous antibiotics within the first 24 hours decrease death from inhalational anthrax, so starting them is the priority and should not wait for laboratory confirmation or isolation. Anthrax is not contagious person to person and requires only standard precautions. Treatment is ciprofloxacin or doxycycline for 60 days because spores can germinate late, and inhalational anthrax has the highest fatality of the three forms.", "whyNot": ["Anthrax is not transmitted person to person, so isolation is not required and delaying antibiotics for it costs time.", "Starting antibiotics within the first 24 hours reduces death, so waiting for laboratory results increases mortality.", "History gathering is important but must not delay the antibiotics that determine survival.", ""]},
    {"id": "n525e3q135", "exam": 6, "topic": "Anthrax forms", "type": "mcq", "bloom": "Analysis", "stem": "A client who handles animal hides develops a painless skin lesion that began as a sore, became a blister, and is now an ulcer with a black center. Which form of anthrax do these findings indicate?", "options": ["Cutaneous anthrax", "Gastrointestinal anthrax", "Inhalational anthrax", "Septicemic anthrax"], "correct": [0], "rationale": "Anthrax has three forms: cutaneous, gastrointestinal and inhalational. The cutaneous form progresses from a sore to a blister to an ulcer with a black center, called an eschar, which reflects the organism's name from the Greek word for coal. Onset occurs within about seven days, and the spores are resistant to heat, cold, drying and disinfectants.", "whyNot": ["", "The gastrointestinal form presents with nausea, anorexia, bloody diarrhea, fever and abdominal pain rather than a skin lesion.", "The inhalational form begins with flu-like symptoms and progresses to cough, chest discomfort, dyspnea and myalgia.", "Septicemic is a form of plague rather than one of the three recognized forms of anthrax."]},
    {"id": "n525e3q136", "exam": 6, "topic": "Smallpox precautions", "type": "mcq", "bloom": "Application", "stem": "A client arrives at the emergency department with high fever, body aches and a generalized rash of vesicles and pustules, many with a central dent, that began on the tongue and mouth and spread to the face and limbs. Which action should the nurse take?", "options": ["Institute standard precautions and begin intravenous antibiotic therapy now", "Institute airborne and contact precautions and notify infection control and public health immediately", "Place the client in droplet precautions and administer the smallpox vaccine", "Isolate the client and wait for laboratory confirmation before notifying anyone else"], "correct": [1], "rationale": "Smallpox spreads person to person by the respiratory route and by contact, and the virus persists on linens and after death, so airborne and contact precautions are used. The rash begins as red spots on the tongue and mouth, becomes vesicles and pustules with a central dent, and spreads to the face, arms and legs, with all lesions in the same stage, which distinguishes it from chickenpox. Care is supportive, exposed contacts and responders are vaccinated, and public health is notified.", "whyNot": ["Smallpox is a virus transmitted person to person, so standard precautions alone would expose others, and antibiotics do not treat it.", "", "Airborne plus contact precautions are needed, and vaccination is directed at exposed contacts and responders rather than being the immediate isolation action.", "Public health and infection control are notified immediately because a single suspected case is a public health emergency."]},
    {"id": "n525e3q137", "exam": 6, "topic": "Botulism priority", "type": "mcq", "bloom": "Analysis", "stem": "A client who ate home-canned vegetables presents with blurred and double vision, drooping eyelids, difficulty swallowing and slurred, weak speech, with progressive weakness moving downward. The client is alert and afebrile. Which nursing action is the priority?", "options": ["Institute airborne precautions to protect other clients and staff", "Encourage ambulation to maintain muscle strength and prevent deconditioning", "Assess respiratory function and prepare for airway and ventilator support", "Delay treatment until stool toxin testing confirms the diagnosis"], "correct": [2], "rationale": "Botulism toxin attacks nerves and produces descending, symmetric flaccid paralysis: blurred or double vision, ptosis, dysphagia, slurred and weak speech, and progressive weakness leading to respiratory failure, with the client afebrile and alert. The priority is assessing respiratory function and preparing for airway and ventilator support. It is not contagious, so standard precautions apply, and antitoxin is obtained from the CDC or health department.", "whyNot": ["Botulism toxin is not contagious, so isolation precautions beyond standard are unnecessary and divert attention from the airway.", "Ambulating a client with progressive descending paralysis is unsafe and does nothing for the impending respiratory failure.", "", "Waiting for confirmation while paralysis ascends toward the respiratory muscles risks respiratory arrest."]},
    {"id": "n525e3q138", "exam": 6, "topic": "Botulism versus pneumonic plague", "type": "mcq", "bloom": "Analysis", "stem": "A nurse is caring for one client with botulism and another with pneumonic plague. Which statement correctly contrasts the infection control needs of these two clients?", "options": ["Both clients require droplet precautions because both affect the respiratory system", "Both clients require only standard precautions because neither spreads person to person", "The client with botulism needs airborne precautions and the client with plague needs standard precautions", "The client with botulism needs standard precautions, while the client with plague needs droplet precautions"], "correct": [3], "rationale": "Botulism toxin is not contagious, so standard precautions apply, and the nursing focus is respiratory muscle function and swallowing because of impending respiratory failure. Pneumonic plague spreads person to person by respiratory droplets, so droplet precautions plus early antibiotics are needed, along with prophylaxis for contacts.", "whyNot": ["Botulism affects breathing through nerve paralysis, not through an organism spread by droplets, so it is not contagious.", "Pneumonic plague does spread person to person by respiratory droplets and requires droplet precautions.", "This reverses both: botulism is not contagious and plague requires droplet precautions.", ""]},
    {"id": "n525e3q139", "exam": 6, "topic": "Plague", "type": "mcq", "bloom": "Analysis", "stem": "A client presents with fever, cough, dyspnea and bloody sputum with rapidly progressing pneumonia after a suspected release of Yersinia pestis. Which combination of actions is most appropriate?", "options": ["Respiratory assessment, droplet isolation and early antibiotics", "Respiratory assessment, standard precautions and supportive care only", "Airborne isolation and vaccination of all exposed contacts", "Contact precautions and observation pending culture results"], "correct": [0], "rationale": "Plague occurs in bubonic, pneumonic and septicemic forms. The pneumonic form spreads person to person by respiratory droplets and presents with fever, cough, dyspnea, bloody sputum and rapid pneumonia, while the bubonic form follows a flea bite and produces painful swollen lymph nodes called buboes. The priority is respiratory assessment plus droplet isolation plus early antibiotics such as gentamicin, streptomycin or a fluoroquinolone.", "whyNot": ["", "Pneumonic plague spreads by respiratory droplets and responds to antibiotics, so standard precautions and supportive care alone are inadequate.", "Droplet precautions are indicated, and prophylactic antibiotics rather than vaccination are used for contacts.", "Delaying antibiotics for culture results is dangerous in a rapidly progressive pneumonia, and contact precautions do not address droplet spread."]},
    {"id": "n525e3q140", "exam": 6, "topic": "Surveillance and cluster recognition", "type": "mcq", "bloom": "Analysis", "stem": "Within a few hours a nurse at an urgent care center sees several residents who attended the same public event, all with similar unexplained symptoms. Which action should the nurse take first?", "options": ["Treat each client individually and document the symptoms carefully", "Notify the local health department immediately", "Advise the clients to return if symptoms worsen over the next 48 hours", "Contact the organizers of the public event to ask what was served"], "correct": [1], "rationale": "A cluster of similar unexplained symptoms in people with a shared exposure requires immediate notification of the local health department for surveillance and investigation, with intentional release suspected, along with appropriate isolation and documentation. Surveillance and early identification are the nurse's secondary prevention role in bioterrorism.", "whyNot": ["Individual treatment and documentation are necessary but miss the cluster, which only the health department can investigate across the community.", "", "Sending a possible exposed cluster home without reporting delays recognition of an intentional release.", "Investigating the source is the health department's role, and contacting organizers directly delays official notification."]},
    {"id": "n525e3q141", "exam": 6, "topic": "Potassium iodide", "type": "mcq", "bloom": "Analysis", "stem": "Residents near a nuclear power plant ask the nurse what potassium iodide will do for them if a radiological release occurs. Which response is accurate?", "options": ["It protects all organs from the effects of radiation exposure", "It removes radioactive particles that have already been inhaled or ingested", "It saturates the thyroid with stable iodine so it cannot absorb radioactive iodine", "It can be taken at any point after exposure and still be fully effective"], "correct": [2], "rationale": "Potassium iodide floods the thyroid with stable, non-radioactive iodine so the gland is saturated and cannot absorb radioactive iodine, reducing thyroid cancer risk, with children and pregnant women as priority groups. It does not protect against external radiation, other radioactive elements such as cesium, or damage to other organs, and it must be taken close to exposure. Shelter-in-place and evacuation remain the main protections.", "whyNot": ["Potassium iodide protects only the thyroid and does nothing for other organs or for external radiation.", "It does not remove or chelate radioactive material; it blocks thyroid uptake of radioactive iodine.", "", "It must be taken close to the time of exposure, which is why residents are told to have it on hand."]},
    {"id": "n525e3q142", "exam": 6, "topic": "Smallpox vaccination planning", "type": "sata", "bloom": "Application", "stem": "A health department is developing a smallpox inoculation plan after a confirmed case. Which groups should the plan include? Select all that apply.", "options": ["People who were exposed to the confirmed case", "First responders", "Health care workers who would care for cases", "Public health staff involved in the response", "Only residents who request vaccination voluntarily", "Residents of states with no reported cases, before any exposure occurs"], "correct": [0, 1, 2, 3], "rationale": "A smallpox inoculation plan includes people who were exposed, first responders, and health care workers and public health staff who would care for cases. The live vaccine is stockpiled by the CDC and state health departments, and exposed contacts and responders are vaccinated while cases are isolated and public health is notified.", "whyNot": ["", "", "", "", "A response plan targets those at risk and those who will provide care rather than waiting for self-referral.", "Mass vaccination of unexposed populations in unaffected areas is not part of the described plan."]},
    {"id": "n525e3q143", "exam": 6, "topic": "Nurse's role in bioterrorism", "type": "mcq", "bloom": "Application", "stem": "A nurse participates in a community drill to test the local bioterrorism response plan and helps ensure that antibiotics for prophylaxis will be available. Which level of prevention do these activities represent?", "options": ["Secondary prevention", "Tertiary prevention", "These activities fall outside the prevention framework", "Primary prevention"], "correct": [3], "rationale": "The nurse's primary prevention role in bioterrorism is planning and preparedness with drills and exercises, designing a response plan, ensuring antibiotics are available for prophylaxis, getting educated and trained, and educating others. Secondary prevention is early identification, screening and trained response, and tertiary is monitoring, referral, plan evaluation, post-event case finding and helping people cope.", "whyNot": ["Secondary prevention is responding with early identification of those exposed or at risk and screening the population.", "Tertiary prevention monitors the population, refers, evaluates the plan and helps people cope after an event.", "Planning and preparedness are explicitly the nurse's primary prevention role in bioterrorism.", ""]},
    {"id": "n525e3q144", "exam": 6, "topic": "Vectors", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse is teaching about how certain infectious agents move between hosts and uses the term vector. Which description defines a vector?", "options": ["A living carrier such as a mosquito, tick or flea that transmits an agent from one host to another", "Any contaminated surface or inanimate object that happens to carry an infectious agent", "The portal of entry through which an agent enters a susceptible host", "A person who harbors an organism without ever showing symptoms of the disease"], "correct": [0], "rationale": "A vector is a living carrier, such as a mosquito, tick or flea, that transmits an infectious agent from one host to another. The flea is the vector in bubonic plague, which illustrates why vector control is part of preparedness.", "whyNot": ["", "This describes a fomite, which is inanimate rather than a living carrier.", "This describes a portal of entry, which is a route rather than a carrier organism.", "This describes an asymptomatic carrier, who is the host rather than the transmitting organism."]},
    {"id": "n525e3q145", "exam": 6, "topic": "Mpox", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse is asked how mpox is transmitted and how it typically presents. Which statement is accurate?", "options": ["It spreads only from animals to humans and never directly between people", "It spreads from animals and between people, with fever occurring before the rash appears", "The rash appears first, and fever develops only in the most severe cases", "It has a short incubation period of only one to two days after exposure"], "correct": [1], "rationale": "Mpox is a viral zoonosis related to smallpox, found in Central and West Africa. It spreads from animal to human through bites, scratches and fluids and from human to human through droplet, skin-to-skin and sexual contact. Incubation is 5 to 21 days, fever occurs before the rash, care is supportive, antivirals exist and vaccine is available for high-risk groups.", "whyNot": ["Human-to-human spread occurs through droplet, skin-to-skin and sexual contact.", "", "The sequence is fever and then rash, which helps distinguish the illness clinically.", "The incubation period is 5 to 21 days, which affects how long contacts must be monitored."]},
    {"id": "n525e3q146", "exam": 6, "topic": "Disaster definition", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse is explaining what distinguishes a disaster from a large emergency. Which statement is accurate?", "options": ["A disaster is any event that results in more than ten deaths", "A disaster is by definition a natural event rather than a human-made one", "A disaster causes destruction and devastation that cannot be relieved without assistance", "A disaster is an event that damages a health care facility itself"], "correct": [2], "rationale": "A disaster is any human-made or natural event causing destruction and devastation that cannot be relieved without assistance. Types include biological, chemical, hazardous materials, nuclear and radiological, explosions, environmental events and electromagnetic pulse. The goals are to reduce or avoid losses, ensure prompt assistance to victims, and achieve rapid, effective recovery.", "whyNot": ["The definition rests on whether outside assistance is required, not on a casualty threshold.", "Disasters may be human-made or natural, including civil unrest, school violence, warfare and terrorism.", "", "That describes an internal disaster, which is one type rather than the general definition."]},
    {"id": "n525e3q147", "exam": 6, "topic": "Disaster phases", "type": "mcq", "bloom": "Analysis", "stem": "A nurse advocates for stronger building codes in a flood-prone area, teaches families to assemble emergency kits, assesses evacuees at a shelter, and refers a displaced family for ongoing mental health support. In which disaster phases do these four activities belong, in order?", "options": ["Preparedness, mitigation, response, recovery", "Mitigation, preparedness, recovery, response", "Response, preparedness, mitigation, recovery", "Mitigation, preparedness, response, recovery"], "correct": [3], "rationale": "Mitigation reduces risk through public education, hazard and vulnerability assessment, improved infrastructure and building codes. Preparedness builds plans, training, exercises, early warning and personal, professional and community readiness. Response minimizes morbidity and mortality through triage, first aid, shelter management and coordination. Recovery restores economic and civil life, including mental health referrals and home visits to find hazards.", "whyNot": ["Advocating for building codes is risk reduction and therefore mitigation, while assembling kits is preparedness, so the first two are reversed.", "Assessing evacuees at a shelter occurs during response, and mental health referral for a displaced family occurs during recovery.", "Advocating for building codes before any event is mitigation, not response.", ""]},
    {"id": "n525e3q148", "exam": 6, "topic": "Phases and prevention levels", "type": "mcq", "bloom": "Analysis", "stem": "A nurse organizes a vaccination campaign in advance of an anticipated outbreak. How should this activity be classified?", "options": ["Mitigation phase and primary prevention", "Response phase and secondary prevention", "Recovery phase and tertiary prevention", "Preparedness phase and secondary prevention"], "correct": [0], "rationale": "Phase and prevention level are different frameworks but they line up: mitigation and preparedness correspond to primary prevention, response to secondary, and recovery to tertiary. A vaccination campaign before an anticipated outbreak is mitigation and primary prevention, triaging injured people is response and secondary, and follow-up referrals for persistent post-disaster problems are recovery and tertiary.", "whyNot": ["", "Response and secondary prevention apply to actions taken after the event begins, such as triaging the injured.", "Recovery and tertiary prevention apply to follow-up for persistent post-disaster problems.", "Preparedness aligns with primary prevention, not secondary, so this pairing is internally inconsistent."]},
    {"id": "n525e3q149", "exam": 6, "topic": "Never self-deploy", "type": "mcq", "bloom": "Application", "stem": "A nurse hears that a tornado has destroyed a town three hours away and wants to help. The nurse is not registered with any disaster response organization. Which action is most appropriate?", "options": ["Drive to the scene and offer nursing assistance at the disaster site", "Get trained and pre-register with a response organization, and report only when assigned", "Travel to the nearest hospital in that town and ask to be put to work", "Collect donated supplies and deliver them directly to the affected area"], "correct": [1], "rationale": "Nurses never self-deploy. Untrained or unassigned volunteers add to the chaos, strain scarce resources such as food, water and shelter, create safety and liability risks, and cannot be integrated into incident command. The correct action is to get trained and pre-register with the Medical Reserve Corps, a Disaster Medical Assistance Team, the American Red Cross or a Community Emergency Response Team, report to the assigned facility per the disaster plan, and wait to be deployed.", "whyNot": ["Self-deploying adds to the chaos, strains scarce food, water and shelter, and creates safety and liability risks.", "", "This is still self-deployment; staffing is directed by the facility's disaster plan and incident command.", "Unsolicited deliveries into a disaster zone consume road capacity and resources that the response needs."]},
    {"id": "n525e3q150", "exam": 6, "topic": "Preparedness activities", "type": "sata", "bloom": "Application", "stem": "A community health nurse is working in the preparedness phase before the next flood season. Which activities belong in this phase? Select all that apply.", "options": ["Helping households build evacuation plans and go-bags", "Identifying and registering residents with home oxygen, dialysis needs or mobility limits", "Participating in drills and mock disasters", "Analyzing past disasters for lessons learned", "Reporting to the scene of a disaster without an assignment", "Assisting displaced families with their insurance claims"], "correct": [0, 1, 2, 3], "rationale": "Preparedness includes personal and family plans and kits covering pets and all family members, knowing workplace and community plans, drills and mock disasters, a professional kit, volunteering with organized teams, educating the community, analyzing past disasters for lessons learned, serving on planning boards, knowing Strategic National Stockpile distribution and points of dispensing, knowing likely targets, and signing up for alerts.", "whyNot": ["", "", "", "", "Self-deployment is specifically identified as inappropriate because it adds to chaos and strains resources.", "Helping with insurance claims occurs during recovery, after the event."]},
    {"id": "n525e3q151", "exam": 6, "topic": "Professional preparedness kit", "type": "sata", "bloom": "Application", "stem": "A nurse is assembling a professional disaster preparedness kit. Which items should the kit contain? Select all that apply.", "options": ["Identification badge, driver's license and proof of licensure and certifications", "Blood pressure cuff, stethoscope and personal protective equipment", "Crank radio, phone charger and flashlight with extra batteries", "Cash or a credit card and laminated important papers and contacts", "Sturdy shoes, weather-appropriate clothing and the nurse's own medications", "Controlled substances borrowed from the workplace medication supply"], "correct": [0, 1, 2, 3, 4], "rationale": "The professional preparedness kit includes an identification badge and driver's license, proof of licensure and certifications, pocket references, a blood pressure cuff and stethoscope, personal protective equipment, a CPR mouth shield and tourniquet, a crank radio and phone charger, cash or a credit card, laminated important papers and contacts, an area map, sun protection, a hat and insect repellent, sturdy shoes and socks, an identification bracelet with medical information and blood type, the nurse's own medications, weather-appropriate clothes, toiletries, a watch and phone, a flashlight with extra batteries, and record-keeping materials.", "whyNot": ["", "", "", "", "", "Removing controlled substances from an employer is unlawful and is not part of any preparedness kit."]},
    {"id": "n525e3q152", "exam": 6, "topic": "Family go-bag", "type": "mcq", "bloom": "Application", "stem": "A nurse helps a family prepare an evacuation go-bag. The household includes an older adult on several medications and a child with a severe food allergy. Which contents are most important to add for these two members?", "options": ["Extra bottled water and additional non-perishable food portions for both of these family members", "A written list of emergency contacts and a designated family meeting place outside the home", "A medication list with copies of prescriptions, and two epinephrine auto-injectors with the allergy action plan", "Blankets, extra clothing and hygiene items sized correctly for each family member"], "correct": [2], "rationale": "A family go-bag holds water at one gallon per person per day for at least three days, non-perishable food, a seven day or longer supply of medications in original containers with a medication list and copies of prescriptions, a first-aid kit, flashlight, batteries, crank radio and charger, copies of identification, insurance and medical records in a waterproof bag, cash, emergency contacts and a meeting place, hygiene items, clothing and blankets, glasses, hearing aids and mobility aids, and pet supplies. For this family the older adult needs medications with the list and prescriptions plus equipment and spare glasses, and the child needs two epinephrine auto-injectors, an allergy action plan, allergen-safe food and medical alert identification.", "whyNot": ["Water and food belong in every go-bag; the question asks what these two members specifically require beyond the basics.", "Contacts and a meeting place are standard go-bag contents for every household rather than needs specific to these members.", "", "These are general go-bag items and do not address the medication and anaphylaxis risks."]},
    {"id": "n525e3q153", "exam": 6, "topic": "Response organizations", "type": "mcq", "bloom": "Analysis", "stem": "A nationwide disaster has been declared by the President. A nurse asks which organization will direct the deployment of Disaster Medical Assistance Teams. Which response is accurate?", "options": ["The American Red Cross", "The Medical Reserve Corps", "The Community Emergency Response Team", "FEMA"], "correct": [3], "rationale": "FEMA directs nurses' response in a nationwide disaster and directs Disaster Medical Assistance Teams under the Federal Response Plan, and works with states in recovery as well as mitigation and preparedness. The American Red Cross directs nurses' actions locally. Initial response is always local, through law enforcement, fire, public health, emergency medical services, Community Emergency Response Teams and the Medical Reserve Corps.", "whyNot": ["The American Red Cross directs nurses' actions locally in shelters and disaster health services and classifies disasters by type, level and scope.", "The Medical Reserve Corps organizes local and national medical volunteers but does not direct national team deployment.", "These are local volunteers activated under FEMA guidance for basic first aid, light search and rescue and fire suppression.", ""]},
    {"id": "n525e3q154", "exam": 6, "topic": "Disaster escalation", "type": "mcq", "bloom": "Analysis", "stem": "A disaster has overwhelmed a town's local resources. Which sequence correctly describes how assistance escalates from this point?", "options": ["Local seeks state assistance, the state notifies FEMA, and the President may declare a major disaster", "The local agency contacts FEMA directly, which then notifies the state government", "The President declares a disaster first, after which the states mobilize resources", "The American Red Cross assumes overall command and requests federal resources"], "correct": [0], "rationale": "Escalation runs from local response to the local jurisdiction seeking state assistance, with the state mobilizing personnel and equipment and the governor declaring a state of emergency and able to request national help; the state then notifies the FEMA Regional Director, the FEMA Director informs the President, and the President declares a major disaster or emergency, after which FEMA directs Disaster Medical Assistance Teams and the national nursing response while the Red Cross directs locally.", "whyNot": ["", "The state is the intermediary; local jurisdictions request state assistance and the state notifies the FEMA Regional Director.", "A presidential declaration follows the escalation through local and state levels rather than beginning it.", "The Red Cross directs nurses locally but does not command the escalation of governmental assistance."]},
    {"id": "n525e3q155", "exam": 6, "topic": "Red Cross and FEMA classification", "type": "mcq", "bloom": "Comprehension", "stem": "A nurse is reviewing how disasters are classified by different organizations. Which statement is accurate?", "options": ["The Red Cross defines scope by the total dollar cost of the relief operation", "FEMA bases its response level on the resources needed rather than on the number of casualties", "FEMA bases its response level on the total number of casualties reported", "The Red Cross defines type by the magnitude of the geographic area affected"], "correct": [1], "rationale": "In the Red Cross classification, type is the agent that caused the disaster, scope is its magnitude and the number of Red Cross units affected, running from single family to local to state to presidentially declared, and level is the relief cost, from level I under $10,000 up to level V over $2.5 million. FEMA's response level is based on the resources needed, not the number of casualties.", "whyNot": ["Cost defines the Red Cross level; scope refers to magnitude and the number of Red Cross units affected.", "", "FEMA's response level is based on the resources needed, not on casualty counts.", "Type refers to the agent that caused the disaster; magnitude relates to scope."]},
    {"id": "n525e3q156", "exam": 6, "topic": "START triage", "type": "mcq", "bloom": "Application", "stem": "Using adult START triage at a mass-casualty scene, the nurse finds an adult who is not breathing. The nurse repositions the airway and the person still does not breathe. Which tag should the nurse apply?", "options": ["Red", "Yellow", "Black", "Green"], "correct": [2], "rationale": "Adult START proceeds by asking everyone who can walk to move to a designated area, which tags them green; asking the rest to wave or move a limb; then for those not breathing, repositioning the airway. If the person still does not breathe the tag is black. If breathing resumes the tag is red, as it is for respirations over 30, no radial pulse, or inability to follow simple commands. All others are yellow.", "whyNot": ["A red tag applies when the person begins breathing after the airway is repositioned, or has a respiratory rate over 30, no radial pulse, or cannot follow commands.", "Yellow is for those who do not meet any red criteria, with major injuries that are not yet life-threatening.", "", "Green is for the walking wounded who were able to get up and move to the designated area at the first step."]},
    {"id": "n525e3q157", "exam": 6, "topic": "Triage tag categories", "type": "mcq", "bloom": "Analysis", "stem": "At a mass-casualty incident the nurse assesses an adult with a sucking chest wound who is in shock but is expected to survive if stabilized. Which triage category applies?", "options": ["Yellow, delayed", "Green, minor", "Black, expectant", "Red, immediate"], "correct": [3], "rationale": "Red means immediate, first priority: life-threatening but expected to survive after stabilization, including airway obstruction, cardiorespiratory failure, significant external hemorrhage, shock, sucking chest wound and burns of the face and neck. Triage separates casualties and allocates treatment based on potential for survival, doing the most good for the most people.", "whyNot": ["Delayed applies to major injuries that are not yet life-threatening and can wait about two hours, such as a penetrating abdominal wound or fractures.", "Green is the walking wounded with minor lacerations, contusions, sprains and superficial burns.", "Black applies to those who are dead or not expected to live, such as burns over 80 percent of body surface area or a head injury with a Glasgow Coma Scale under 8.", ""]},
    {"id": "n525e3q158", "exam": 6, "topic": "JumpSTART pediatric triage", "type": "mcq", "bloom": "Analysis", "stem": "Using pediatric JumpSTART triage, the nurse finds a child who is apneic but has a palpable pulse. The nurse repositions the airway without effect and then gives five rescue breaths, after which the child begins breathing. Which tag should the nurse apply?", "options": ["Red", "Black", "Yellow", "Green"], "correct": [0], "rationale": "Pediatric JumpSTART differs from adult START by adding rescue breaths. A child able to walk without major injuries is green and re-evaluated. If apneic, the airway is repositioned; if breathing resumes the tag is red. If apneic with a pulse, five rescue breaths are given; if breathing resumes the tag is red, and if the child remains apneic the tag is black, as it is for a child who is apneic with no pulse.", "whyNot": ["", "Black applies when the child remains apneic after five rescue breaths, or is apneic with no pulse.", "Yellow is for children who meet none of the red criteria and are alert, responsive to voice, or appropriately responsive to pain.", "Green is for children able to walk with no major injuries, who are then re-evaluated."]},
    {"id": "n525e3q159", "exam": 6, "topic": "Glasgow Coma Scale", "type": "mcq", "bloom": "Application", "stem": "A nurse assesses a trauma victim and documents a Glasgow Coma Scale score of 7 with abnormal extension to painful stimulus. How should the nurse interpret these findings?", "options": ["The client is comatose and is demonstrating decorticate posturing", "The client is comatose and is demonstrating decerebrate posturing", "The client is drowsy but not comatose, with normal motor responses", "The client is totally unresponsive with the lowest possible score"], "correct": [1], "rationale": "The Glasgow Coma Scale scores eye opening 1 to 4, verbal response 1 to 5 and motor response 1 to 6, for a best score of 15. A score of 8 or less indicates coma and 3 means totally unresponsive. Decorticate posturing is abnormal flexion scoring 3, and decerebrate posturing is abnormal extension scoring 2.", "whyNot": ["Decorticate posturing is abnormal flexion scoring 3 on the motor component, while abnormal extension is decerebrate.", "", "A score of 8 or less indicates coma, and abnormal extension is not a normal motor response.", "The lowest possible score is 3, which indicates total unresponsiveness; this client scores 7."]},
    {"id": "n525e3q160", "exam": 6, "topic": "Shelter: identifying the phase", "type": "mcq", "bloom": "Analysis", "stem": "The nurse is documenting the shelter's activities for the emergency management agency. Which phase of the disaster management cycle do the nurse's current activities represent?", "options": ["Preparedness", "Mitigation", "Response", "Recovery"], "correct": [2], "rationale": "Response minimizes morbidity and mortality by saving lives, coordinating communication, and managing evacuation or shelter-in-place. The nurse's role in response includes triage, first aid, shelter management, ongoing assessment and surveillance reports, infection control, and communication with hospitals, the Red Cross, the Medical Reserve Corps and the health department. Response corresponds to secondary prevention.", "whyNot": ["Preparedness covers planning, training, drills and building kits before the event occurs.", "Mitigation reduces risk in advance through building codes, hazard assessment and infrastructure improvement.", "", "Recovery restores economic and civil life afterward, including mental health referrals and home visits for hazards."], "caseId": "c6shelter", "caseTitle": "Case 6 - A hurricane evacuation shelter", "scenario": "A hurricane has made landfall and a regional shelter has opened in a high school gymnasium. A community health nurse has been assigned to the shelter by the local emergency management agency. Among the 180 evacuees are a 62-year-old man with type 2 diabetes who evacuated without his insulin or any of his other medications, a visitor to the area who speaks only Portuguese and cannot understand the announcements, an 80-year-old woman who uses a wheelchair and needs help to reach the restrooms, and a family whose two young children have been crying and refusing to sleep since the evacuation."},
    {"id": "n525e3q161", "exam": 6, "topic": "Shelter: priority setting", "type": "mcq", "bloom": "Analysis", "stem": "The nurse must decide which evacuee to address first. Which action takes priority?", "options": ["Secure a qualified Portuguese interpreter for the visitor", "Arrange an accessible sleeping area near the restrooms for the woman who uses a wheelchair", "Reassure the parents that the children's sleep problems are a common reaction", "Assess the blood glucose of the man who evacuated without his insulin and obtain his medications"], "correct": [3], "rationale": "A client with type 2 diabetes who has been without insulin and other medications is at immediate physiologic risk, so assessing glucose and obtaining insulin, medications and food comes first, with referral for medical care if he is unstable. The interpreter, the accessible and safe space with fall prevention and toileting support, and reassurance about children's reactions follow, along with infection control and documentation.", "whyNot": ["Interpretation is essential and must be arranged, but it does not carry the immediate physiologic risk of untreated diabetes.", "Accessibility and fall prevention are important needs but are not as time-critical as uncontrolled blood glucose.", "Teaching about expected reactions is appropriate but is the least urgent of the four needs.", ""], "caseId": "c6shelter", "caseTitle": "Case 6 - A hurricane evacuation shelter", "scenario": "A hurricane has made landfall and a regional shelter has opened in a high school gymnasium. A community health nurse has been assigned to the shelter by the local emergency management agency. Among the 180 evacuees are a 62-year-old man with type 2 diabetes who evacuated without his insulin or any of his other medications, a visitor to the area who speaks only Portuguese and cannot understand the announcements, an 80-year-old woman who uses a wheelchair and needs help to reach the restrooms, and a family whose two young children have been crying and refusing to sleep since the evacuation."},
    {"id": "n525e3q162", "exam": 6, "topic": "Shelter: vulnerable groups", "type": "sata", "bloom": "Comprehension", "stem": "The nurse reviews which groups suffer most in disasters so they can be prioritized in future planning. Which groups belong on that list? Select all that apply.", "options": ["People with low income and people who are unhoused", "People with disabilities, chronic disease or mental illness", "People who do not speak English, and tourists", "Children and pregnant women", "People who are hearing or visually impaired and undocumented residents", "Residents who have completed community disaster training"], "correct": [0, 1, 2, 3, 4], "rationale": "Those who suffer most in disasters, and therefore should be prepared in advance, include people with low income, people who are unhoused, people with disabilities, chronic disease or mental illness, people who do not speak English, tourists, children, pregnant women, people who are hearing or visually impaired, and undocumented residents. This shelter contains four of these groups at once.", "whyNot": ["", "", "", "", "", "Trained residents are better prepared than average, which is the reason such training is promoted during the preparedness phase."], "caseId": "c6shelter", "caseTitle": "Case 6 - A hurricane evacuation shelter", "scenario": "A hurricane has made landfall and a regional shelter has opened in a high school gymnasium. A community health nurse has been assigned to the shelter by the local emergency management agency. Among the 180 evacuees are a 62-year-old man with type 2 diabetes who evacuated without his insulin or any of his other medications, a visitor to the area who speaks only Portuguese and cannot understand the announcements, an 80-year-old woman who uses a wheelchair and needs help to reach the restrooms, and a family whose two young children have been crying and refusing to sleep since the evacuation."},
    {"id": "n525e3q163", "exam": 6, "topic": "Shelter: ongoing surveillance", "type": "mcq", "bloom": "Analysis", "stem": "The nurse has completed an initial assessment of all 180 evacuees. A colleague suggests that the assessment work is now finished. Which response by the nurse is most accurate?", "options": ["\"Ongoing assessment and surveillance reports are as important as the initial assessment.\"", "\"You are right, our remaining task is first aid for anyone who becomes injured.\"", "\"The initial assessment is complete, so we should now focus only on record keeping.\"", "\"Further assessment should wait until the health department requests specific data.\""], "correct": [0], "rationale": "Ongoing assessment and surveillance reports are as important as the initial assessment because they show the population's status and the effectiveness of relief. Shelter management duties for nurses include triage and first aid, record keeping, assessment and referral, infection control and safety, and communication with the local emergency department about capacity, the Red Cross, the Medical Reserve Corps and the health department.", "whyNot": ["", "Limiting the role to reactive first aid abandons the surveillance that detects emerging illness in a crowded shelter.", "Record keeping is one shelter duty among several and does not replace continuing assessment of the population.", "Surveillance reports are generated continuously to show the population's status rather than only on request."], "caseId": "c6shelter", "caseTitle": "Case 6 - A hurricane evacuation shelter", "scenario": "A hurricane has made landfall and a regional shelter has opened in a high school gymnasium. A community health nurse has been assigned to the shelter by the local emergency management agency. Among the 180 evacuees are a 62-year-old man with type 2 diabetes who evacuated without his insulin or any of his other medications, a visitor to the area who speaks only Portuguese and cannot understand the announcements, an 80-year-old woman who uses a wheelchair and needs help to reach the restrooms, and a family whose two young children have been crying and refusing to sleep since the evacuation."},
    {"id": "n525e3q164", "exam": 6, "topic": "Recovery: psychosocial support", "type": "sata", "bloom": "Application", "stem": "Weeks later, during recovery, the children are still having sleep problems and several responders have become irritable and withdrawn. Which nursing actions are appropriate? Select all that apply.", "options": ["Refer affected individuals to mental health professionals or crisis counseling", "Teach the parents that regression and sleep problems are common after a disaster", "Help the parents reassure the children and keep familiar routines", "Encourage responders to take breaks, debrief and use employee assistance resources", "Tell the responders that distress indicates they are unsuited to disaster work", "Advise the parents to avoid discussing the hurricane with the children at all"], "correct": [0, 1, 2, 3], "rationale": "During recovery the nurse refers for mental health support, teaches parents that regression and sleep problems are common and how to reassure children and keep routines, and encourages responders to take breaks, debrief and use employee assistance resources. Signs warranting referral include excessive worry, frequent crying, increased irritability, anger or arguing, anxiety, trouble thinking, increased substance use, more physical complaints, wanting to be alone and sleep trouble. Workers experience the same distress and should walk away and take a break.", "whyNot": ["", "", "", "", "Workers experience the same distress as survivors; framing it as unsuitability discourages them from seeking the support they need.", "Avoiding the subject does not help children process the event; reassurance and routine are what the material recommends."], "caseId": "c6shelter", "caseTitle": "Case 6 - A hurricane evacuation shelter", "scenario": "A hurricane has made landfall and a regional shelter has opened in a high school gymnasium. A community health nurse has been assigned to the shelter by the local emergency management agency. Among the 180 evacuees are a 62-year-old man with type 2 diabetes who evacuated without his insulin or any of his other medications, a visitor to the area who speaks only Portuguese and cannot understand the announcements, an 80-year-old woman who uses a wheelchair and needs help to reach the restrooms, and a family whose two young children have been crying and refusing to sleep since the evacuation."},
    {"id": "n525e3q165", "exam": 6, "topic": "Internal versus external disaster", "type": "mcq", "bloom": "Analysis", "stem": "A hospital is notified that multiple casualties are arriving after a tornado struck a nearby town. The hospital itself is undamaged. How should the nurse classify this situation?", "options": ["An internal disaster because the hospital must activate its disaster plan", "An external disaster that increases demand for the facility's services", "An external disaster that requires evacuation of current inpatients", "Neither, because the tornado struck a different town"], "correct": [1], "rationale": "An internal disaster involves the facility itself and threatens staff and patients, such as an in-house fire, a chemical spill, or an earthquake that damages the building. An external disaster does not damage the facility but affects it through the number of patients arriving, and usually affects a large part of the community, as with a tornado or a mass shooting.", "whyNot": ["Activating the plan happens in both types; an internal disaster involves damage or threat to the facility itself.", "", "Stable patients may be discharged or relocated to free beds, but evacuation of the facility is not indicated when the building is intact.", "An external disaster typically affects a large part of the community and reaches the facility through the number of patients arriving."]},
    {"id": "n525e3q166", "exam": 6, "topic": "Charge nurse response to a disaster", "type": "mcq", "bloom": "Application", "stem": "A hospital declares a major external disaster and expects a large number of casualties. Which action should the charge nurse take first?", "options": ["Reassign a nurse from the unit to the emergency department", "Begin teaching the staff the components of the facility disaster plan", "Make rounds with the discharge officer to identify clients who can be discharged", "Contact the families of current inpatients to inform them of the situation"], "correct": [2], "rationale": "In an external disaster the facility must make room for casualties, so the charge nurse's first action is to round with the discharge officer to identify clients who can be discharged with services or relocated, such as to a skilled nursing facility. Unstable clients with active bleeding or a low Glasgow Coma Scale are kept. The disaster plan dictates staffing, so individual reassignment is not the charge nurse's independent decision.", "whyNot": ["Staffing assignments are dictated by the facility's disaster plan and incident command rather than by individual unit decisions.", "Staff are trained on the plan in advance; teaching it during an active event consumes time that is needed for patient flow.", "", "Family notification is not the first priority when beds must be freed for incoming casualties."]},
    {"id": "n525e3q167", "exam": 6, "topic": "Selecting clients for discharge", "type": "mcq", "bloom": "Analysis", "stem": "During an external disaster a nurse must identify which surgical client can be discharged to free a bed. Which client is the most appropriate choice?", "options": ["A client with a bleeding ulcer whose hemoglobin is 7 g/dL", "A client with a Glasgow Coma Scale of 6 and decorticate posturing", "A client scheduled for repair of an abdominal aortic aneurysm", "A client who is two days post-hysterectomy and recovering without complications"], "correct": [3], "rationale": "To make room for casualties the facility discharges with services or relocates stable, ambulatory clients and keeps those who are unstable, including clients with active bleeding or a low Glasgow Coma Scale. The client two days after an uncomplicated hysterectomy is the most stable of these four and is therefore the appropriate choice.", "whyNot": ["Active bleeding with a hemoglobin of 7 makes this client unstable, and unstable clients are kept.", "A score of 6 indicates coma and this client is critically ill and must remain.", "The aneurysm is still unrepaired and carries a risk of rupture, so this client stays.", ""]},
    {"id": "n525e3q168", "exam": 6, "topic": "Levels of prevention in disaster management", "type": "mcq", "bloom": "Analysis", "stem": "A nurse makes home visits after a flood to find hazards such as damaged wiring and standing water that could cause further injury. Which level of prevention does this activity represent?", "options": ["Tertiary prevention", "Primary prevention", "Secondary prevention", "This activity is outside the prevention framework"], "correct": [0], "rationale": "In disaster management, primary prevention is developing the community disaster plan, secondary prevention is assessing and triaging victims, and tertiary prevention is home visits to uncover dangers that may cause further injury. Recovery-phase nursing also includes teaching hygiene, updating immunizations, mental health referrals, watching for regression in children, addressing environmental hazards such as live and dead animals, and case finding and referral.", "whyNot": ["", "Primary prevention in disaster management is developing the community disaster plan before an event.", "Secondary prevention is assessing and triaging victims during the response.", "Post-disaster home visits to uncover ongoing dangers are explicitly identified as tertiary prevention."]}
  ]
};
